comms.text:
@1 וְאַתְּ תְּפַקֵד יָת בְּנֵי יִשְׂרָאֵל וְיִסְבוּן לָךְ מִשְׁחָא זֵיתָא דַכְיָא כָּתִישָׁא לְאַנְהָרָא לְאַדְלָקָא בוֹצִינַיָא תְּדִירָא:
@2 בְּמַשְׁכַּן זִמְנָא מִבָּרָא לְפָרֻכְתָּא דְעַל סַהֲדוּתָא יְסַדַר יָתֵהּ אַהֲרֹן וּבְנוֹהִי מֵרַמְשָׁא עַד צַפְרָא קָדָם יְיָ קְיָם עֲלָם לְדָרֵיהוֹן מִן בְּנֵי יִשְׂרָאֵל:וְ
@3 אַתְּ קָרֵב לְוָתָךְ יָת אַהֲרֹן אָחוּךְ וְיָת בְּנוֹהִי עִמֵהּ מִגוֹ בְּנֵי יִשְׂרָאֵל לְשַׁמָשָׁא קֳדָמַי אַהֲרֹן נָדָב וַאֲבִיהוּא אֶלְעָזָר וְאִיתָמָר בְּנֵי אַהֲרֹן:
@4 וְתַעְבֵּד לְבוּשֵׁי קוּדְשָׁא לְאַהֲרֹן אָחוּךְ לִיקָר וּלְתֻשְׁבְּחָן:
@5 וְאַתְּ תְּמַלֵל עִם כָּל חַכִּימֵי לִבָּא דְאַשְׁלֵמִית עִמֵהּ רוּחַ חָכְמְתָא וְיַעְבְּדוּן יָת לְבוּשֵׁי אַהֲרֹן לְקַדָשׁוּתֵהּ לְשַׁמָשָׁא קֳדָמַי:
@6 וְאִלֵין לְבוּשַׁיָא דִי יַעְבְּדוּן חוּשְׁנָא וְאֵפוֹדָא וּמְעִילָא וְכִתּוּנָא מְרַמְצָא מִצְנֶפְתָּא וְהֶמְיָנָא וְיַעְבְּדוּן לְבוּשֵׁי קוּדְשָׁא לְאַהֲרֹן אָחוּךְ וְלִבְנוֹהִי לְשַׁמָשָׁא קֳדָמַי:
@7 וְאִנוּן יִסְבוּן יָת דַהֲבָא וְיָת תִּכְלָא וְיָת אַרְגְוָנָא וְיָת צְבַע זְהוֹרִי וְיָת בּוּצָא:
@8 וְיַעְבְּדוּן יָת אֵפוֹדָא דַהֲבָא תִּכְלָא וְאַרְגְוָנָא צְבַע זְהוֹרִי וּבוּץ שְׁזִיר עוֹבַד אֳמָן:
@9 תַּרְתֵּין כַּתְפִּין מְלַפְּפָן יְהוֹן לֵהּ עַל תְּרֵין סִטְרוֹהִי וְיִתְלָפַף:
@10 וְהֶמְיַן תִּקוּנֵי דִי עֲלוֹהִי כְּעוֹבָדוֹהִי מִנֵהּ יְהֵי דַהֲבָא תִּכְלָא וְאַרְגְּוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר:
@11 וְתִסַב יָת תַּרְתֵּין אַבְנֵי בוּרְלָא וְתִגְלוֹף עֲלֵיהֶן שְׁמָהַת בְּנֵי יִשְׂרָאֵל:
@12 שִׁתָּא מִשְׁמָהָתְהוֹן עַל אַבְנָא חֲדָא וְיָת שְׁמָהַת שִׁתָּא דְאִשְׁתָּאָרוּ עַל אַבְנָא תִנְיֵתָא כְּתוּלְדָתְהוֹן:
@13 עוֹבַד אֳמָן אֶבֶן טָבָא כְּתַב מְפָרַשׁ כִּגְלֹף דְעִזְקָא תִגְלוֹף יָת תַּרְתֵּין אַבְנַיָא עַל שְׁמָהַת בְּנֵי יִשְׂרָאֵל מְשַׁקְעָן מְרַמְצָן דִדְהַב תַּעְבֵּד יָתְהוֹן:
@14 וּתְשַׁוִּי יָת תַּרְתֵּין אַבְנַיָא עַל כִּתְפֵּי אֵפוֹדָא אַבְנֵי דָכְרָנָא לִבְנֵי יִשְׂרָאֵל וְיִטּוֹל אַהֲרֹן יָת שְׁמָהָתְהוֹן קֳדָם יְיָ עַל תְּרֵין כִּתְפּוֹהִי לְדָכְרָנָא:
@15 וְתַעְבֵּד מְרַמְצָן דִדְהַב:
@16 וְתַרְתֵּין תִּכִּין דְהַב דְכֵי מְתַחְמָן תַּעְבֵד יָתְהוֹן עוֹבַד גְדִילוּ וְתִתֵּן יָת תִּכַּיָא גְדִילָתָא עַל מְרַמְצָתָא:
@17 וְתַעְבֵּד חשֶׁן דִינָא עוֹבַד אֳמָן כְּעוֹבַד אֵפוֹדָא תַּעְבְּדִנֵהּ דַהֲבָא תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר תַּעְבֵּד יָתֵהּ:
@18 מְרַבַּע יְהֵי עֵיף זֶרְתָּא אֻרְכֵּה וְזֶרְתָּא פְתָיֵהּ:
@19 וְתַשְׁלֵם בֵּה אַשְׁלָמוּת אַבְנָא אַרְבְּעָא סִדְרִין אֶבֶן טָּבָא סִדְרָא קַדְמָאָה םַמְקָן יַרְקָן וּבַרְקָן סִדְרָא חָד:
@20 וְסִדְרָא תִּנְיָנָא אִזְמָרַגְדִין וְשַׁבְזִיז וְסִבְהֲלוֹם:
@21 וְסִדְרָא תְּלִיתָאָה קַנְכִּירֵי טַרְקְיָא וְעֵין עֶגְלָא:
@22 וְסִדְרֵא רְבִיעָאָה כְּרוּם יַמָא וּבוּרְלָא וּפַנְטֵרֵי מְרַמְצָן דִדְהַב יְהוֹן בְּאַשְׁלָמוּתְהוֹן:
@23 וְאַבְנַיָא יְהֶוְיַן עַל שְׁמָהַת בְּנֵי יִשְׂרָאֵל תַּרְתֵּי עֶסְרֵי עַל שְׁמָהַתְהוֹן כְּתַב מְפָרַשׁ כִּגְלוֹף דְעִזְקָא גְבַר עַל שְׁמֵהּ תְּהֶוְיָן לִתְרֵין עֲסַר שִׁבְטִין:
@24 וְתַעְבֵּד עַל חוּשְׁנָא תִּכִּין מְתַחְמָן עוֹבַד גְדִילוּ דְהַב דְכֵי:
@25 וְתַעְבֵּד עַל חוּשְׁנָא תַּרְתֵּין עִזְקָן דִדְהַב וְתִתֵּן יָת תַּרְתֵּין עִזְקָתָא עַל תְּרֵין סִטְרֵי חוּשְׁנָא:
@26 וְתִתֵּן יָת תַּרְתֵּין גְדִילָן דִדְהַב עַל תַּרְתֵּין עִזְקָתָא לְסִטְרֵי חוּשְׁנָא:
@27 וְיָת תַּרְתֵּין גְדִילָן דְעַל תַּרְתֵּין סִטְרוֹהִי תִּתֵּן עַל תַּרְתֵּין מְרַמְצָתָא וְתִתֵּן עַל כִּתְפֵּי אֵפוֹדָא לָקֳבֵל אַפּוֹהִי:
@28 וְתַעְבֵּד תַּרְתֵּין עִזְקָן דִדְהַב וּתְשַׁוִּי יָתְהוֹן עַל תְּרֵין סִטְרֵי חוּשְׁנָא עַל סִפְתֵהּ דִי לְעִבְרָא דְאֵפוֹדָא מִלְגָו:
@29 וְתַעְבֵּד תַּרְתֵּין עִזְקָן דִדְהַב וְתִתֵּן יָתְהוֹן עַל תַּרְתֵּין כִּתְפֵּי אֵפוֹדָא מִלְרַע מִלְקֳבֵל אַפּוֹהִי לָקֳבֵל בֵּית לוֹפֵי מֵעִלָוֵי לְהֶמְיַן אֵפוֹדָא:
@30 וְיֶחְדוּן יָת חוּשְׁנָא מֵעִזְקְתֵהּ לְעִזְקְתָא דְאֵפוֹדָא בְּחוּטָא דִתְכֶלְתָּא לְמֶהֱוֵי עַל הֶמְיַן אֵפוֹדָא וְלָא יִתְפָּרֵק חוּשְׁנָא מֵעִלָוֵי אֵפוֹדָא:
@31 וְיִטוֹל אַהֲרֹן יָת שְׁמָהַת בְּנֵי יִשְׂרָאֵל בְּחשֶׁן דִינָא עַל לִבֵּהּ בְּמֵעֲלֵהּ לְקוּדְשָׁא לְדוּכְרָנָא קֳדָם יְיָ תְּדִירָא:
@32 וְתִתֵּן בְּחשֶׁן דִינָא יָת אוּרַיָא וְיָת תֻּמַיָא וִיהוֹן עַל לִבָּא דְאַהֲרֹן בְּמֵעֲלֵהּ קֳדָם יְיָ וְיִטוֹל אַהֲרֹן יָת דִינָא דִבְנֵי יִשְׂרָאֵל עַל לִבֵּהּ קֳדָם יְיָ תְּדִירָא:
@33 וְתַעְבֵּד יָת מְעִילָא דְאֵפוֹדָא גְמִיר תִּכְלָא:
@34 וִיהֵי פוּם רֵישֵׁהּ כָּפִיל לְגַוֵּהּ תּוֹרָא יְהֵא מַקַף לְפוּמֵהּ סְחוֹר סְחוֹר עוֹבַד מָחֵי כְּפוּם שִׂרְיָן יְהֵי לֵהּ לָא יִתְבְּזָע:
@35 וְתַעְבֵּד עַל שִׁיפוֹלוֹהִי רִמוֹנֵי תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי עַל שִׁיפוֹלוֹהִי סְחוֹר סְחוֹר וְזַגִין דְדַהֲבָא בֵּינֵיהוֹן סְחוֹר סְחוֹר:
@36 זַגָא דְדַהֲבָא וְרִמוֹנָא זַגָא דְדַהֲבָא וְרִמוֹנָא עַל שִׁיפוֹלֵי מְעִילָא סְחוֹר סְחוֹר:
@37 וִיהֵי עַל אַהֲרֹן לְשַׁמָשָׁא וְיִשְׁתְּמַע קָלֵהּ בְּמֵעֲלֵהּ לְקוּדְשָׁא קֳדָם יְיָ וּבְמִפְקֵהּ וְלָא יְמוּת:
@38 וְתַעְבֵּד צִיצָא דִדְהַב דְכֵי וְתִגְלוֹף עֲלוֹהִי כְּתַב מִפָרַשׁ קֹדֶשׁ לַיָי:
@39 וּתְשַׁוִי יָתֵהּ עַל חוּטָא דִתְכֶלְתָּא וִיהֵי עַל מִצְנֶפְתָּא לָקֳבֵל אַפֵּי מִצְנֶפְתָּא יְהֵי:
@40 וִיהֵי עַל בֵּית עֵינוֹהִי דְאַהֲרֹן וְיִטּוֹל אַהֲרֹן יָת עֲוָיַת קוּדְשַׁיָא דִי יְקַדְשׁוּן בְּנֵי יִשְׂרָאֵל לְכָל מַתְּנַּת קוּדְשֵׁיהוֹן וִיהֵי עַל בֵּית עֵינוֹהִי תְּדִירָא לְרַעֲוָא לְהוֹן קֳדָם יְיָ:
@41 וּתְרַמֵץ כִּתּוּנָא בוּצָא וְתַעְבֵּד מִצְנֶפְתָּא דְבוּצָא וְהֶמְיָנָא תַּעְבֵּד עוֹבַד צַיָר:
@42 וְלִבְנֵי אַהֲרֹן תַּעְבֵּד כִּתּוּנִין וְתַעְבֵּד לְהוֹן הֶמְיָנִין וְכוֹבָעִין תַּעְבֵּד לְהוֹן לִיקָר וּלְתֻשְׁבְּחָן:
@43 וְתַלְבֵּש יָתְהוֹן יָת אַהֲרֹן אָחוּךְ וְיָת בְּנוֹהִי עִמֵהּ וּתְרַבֵּי יָתְהוֹן וּתְקָרֵב יָת קֻרְבָּנְהוֹן וּתְקַדֵשׁ יָתְהוֹן וִישַׁמְשׁוּן קֳדָמַי:
@44 וְעִבֵד לְהוֹן מִכְנְסִין דְבוּץ לְכַסָאָה בְשַׂר עֶרְיְתָא מֵחַרְצָן וְעַד יַרְכָּן יְהוֹן:
@45 וִיהוֹן עַל אַהֲרֹן וְעַל בְּנוֹהִי בְּמֵעַלְהוֹן לְּמַשְׁכַּן זִמְנָא אוֹ בְמִקְרָבְהוֹן לְמַדְבְּחָא לְשַׁמָשָׁא בְקוּדְשָׁא וְלָא יְקַבְּלוּן חוֹבָא וִימוּתוּן קְיָם עָלָם לֵהּ וְלִבְנוֹהִי בַתְרוֹהִי:
@46 וְדֵין פִּתְגָמָא דִי תַעְבֵּד לְהוֹן לְקַדָשָׁא יָתְהוֹן לְשַׁמָשָׁא קֳדָמַי סַב תּוֹר חָד בַּר תּוֹרֵי וְדִכְרִין תְּרֵין שַׁלְמִין:
@47 וּלְחֵם פַּטִיר וּגְרִיצִין פַּטִּירִין דְפִילָן בִּמְשַׁח וְאֶסְפּוֹגִין פַּטִּירִין דִמְשִׁיחִין בִּמְשָׁח סֻלְתָּא חִטִין תַּעְבֵּד יָתְהוֹן:
@48 וְתִתֵּן יָתְהוֹן עַל סַלָא חַד וּתְקָרֵב יָתְהוֹן בְּסַלָא וְיָת תּוֹרָא וְיָת תְּרֵין דִכְרִין:
@49 וְיָת אַהֲרֹן וְיָת בְּנוֹהִי תְּקָרֵב לִתְרַע מַשְׁכַּן זִמְנָא וְתַסְחֵי יָתְהוֹן בְּמַיָא:
@50 וְתִסַב יָת לְבוּשַׁיָא וְתַלְבֵּשׁ יָת אַהֲרֹן יָת כִּתּוּנָא וְיָת מְעִיל אֵפוֹדָא וְיָת אֵפוֹדָא וְיָת חוּשְׁנָא וְתַתְקֵן לֵהּ בְּהֶמְיַן אֵפוֹדָא:
@51 וּתְשַׁוִי מִצְנֶפְתָּא עַל רֵישֵׁהּ וְתִתֵּן יָת כְּלִילָא דְקוּדְשָׁא עַל מִצְנֶפְתָּא:
@52 וְתִסַב יָת מִשְׁחָא דִרְבוּתָא וּתְרִיק עַל רֵישֵׁהּ וּתְרַבֵּהּ יָתֵהּ:
@53 וְיָת בְּנוֹהִי תְּקָרֵב וְתַלְבֵּשִׁנוּן כִּתּוּנִין:
@54 וּתְזָרֵז יָתְהוֹן הֶמְיָנִין אַהֲרֹן וּבְנוֹהִי וְתַתְקֵן לְהוֹן כּוֹבָעִין וּתְהֵי לְהוֹן כְּהֻנְתָּא לִקְיַם עָלָם וּתְקָרֵב קֻרְבָּנָא דְאַהֲרֹן וְקֻרְבָּנָא דִבְנוֹהִי:
@55 וּתְקָרֵב יָת תּוֹרָא לִקֳדָם מַשְׁכַּן זִמְנָא וְיִסְמוֹךְ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ תּוֹרָא:
@56 וְתִכּוֹס יָת תּוֹרָא קֳדָם יְיָ בִּתְרַע מַשְׁכַּן זִמְנָא:
@57 וְתִסַב מִדְמָא דְתוֹרָא וְתִתֵּן עַל קַרְנַת מַדְבְּחָא בְּאֶצְבְּעָךְ וְיָת כָּל דְמָא תֵישׁוֹד לִיסוֹדָא דְמַדְבְּחָא:
@58 וְתִסַב יָת כָּל תַּרְבָּא דְחָפֵי יָת גַוָא וְיָת חִצְרָא דִעַל כַּבְדָא וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבָּא דִי עֲלֵיהֶן וְתַסֵיק לְמַדְבְּחָא:
@59 וְיָת בִּסְרָא דְתוֹרָא וְיָת מַשְׁכֵהּ וְיָת אוּכְלֵהּ תּוֹקִיד בְּנוּרָא מִבָּרָא לְמַשְׁרִיתָא חַטָאתָא הוּא:
@60 וְיָת דִכְרָא חַד תִּסַב וְיִסְמְכוּן אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ דִכְרָא:
@61 וְתִכּוֹס יָת דִכְרָא וְתִסַב יָת דְמֵהּ וְתִזְרוֹק עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@62 וְיָת דִכְרָא תְּפַלֵג לְאֵבָרוֹהִי וּתְחַלִיל גַּוֵהּ וּכְרָעוֹהִי וְתִתֵּן עַל אֵבָרוֹהִי וְעַל רֵישֵׁהּ:
@63 וְתַסֵיק יָת כָּל דִכְרָא לְמַדְבְּחָא עֲלָתָא הוּא קֳדָם יְיָ לְאִתְקַבָּלָא בְרַעֲוָא קֻרְבָּנָא קֳדָם יְיָ הוּא:
@64 וְתִסַב יָת דִכְרָא תִנְיָנָא וְיִסְמוֹךְ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ דִכְרָא:
@65 וְתִכּוֹס יָת דִכְרָא וְתִסַב מִדְמֵהּ וְתִתֵּן עַל רוּם אוּדְנָא דְאַהֲרֹן וְעַל רוּם אוּדְנָא דִבְנוֹהִי דְיַמִינָא וְעַל אִלְיוֹן יְדֵיהוֹן דְיַמִינָא וְעַל אִלְיוֹן רַגְלֵיהוֹן דְיַמִינָא וְתִזְרוֹק יָת דְמָא עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@66 וְתִסַב מִן דְמָא דִי עַל מַדְבְּחָא וּמִמִשְׁחָא דִרְבוּתָא וְתַדֵי עַל אַהֲרֹן וְעַל לְבוּשׁוֹהִי וְעַל בְּנוֹהִי וְעַל לְבוּשֵׁי בְנוֹהִי עִמֵהּ וְיִתְקַדַשׁ הוּא וּלְבוּשׁוֹהִי וּבְנוֹהִי וּלְבוּשֵׁי בְנוֹהִי עִמֵהּ:
@67 וְתִסַב מִן דִכְרָא תַּרְבָּא וְאַלִיתָא וְיָת תַּרְבָּא דְחָפֵי יָת גַוָא וְיָת חֲצַר כַּבְדָא וְיָת תַּרְתֵּן כָּלְיָן וְיָת תַּרְבָּא דִי עֲלֵיהֶן וְיָת שׁוֹקָא דְיַמִינָא אֲרֵי דְכַר קֻרְבָּנָא הוּא:
@68 וּפִתָּא דִלְחֵם חַד וּגְרִצְתָּא דִלְחֵם מְשַׁח חֲדָא וְאֶסְפּוֹג חָד מִסַלָא דְפַטִירַיָא דִי קֳדָם יְיָ:
@69 וּתְשַׁוֵי כֹלָא עַל יְדָא דְאַהֲרֹן וְעַל יְדָא דִבְנוֹהִי וּתְרִים יָתְהוֹן אֲרָמוּתָא קֳדָם יְיָ:
@70 וְתִסַב יָתְהוֹן מִידֵיהוֹן וְתַסֵיק לְמַדְבְּחָא עַל עֲלָתָא לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ קֻרְבָּנָא הוּא קֳדָם יְיָ:
@71 וְתִסַב יָת חֶדְיָא מִדְכַר קֻרְבָּנַיָא דִי לְאַהֲרֹן וּתְרִים יָתֵהּ אֲרָמוּתָא קֳדָם יְיָ וִיהֵי לָךְ לָחֳלָק:
@72 וּתְקַדֵשׁ יָת חֶדְיָא דַאֲרָמוּתָא וְיָת שׁוֹקָא דְאַפְרָשׁוּתָא דִי אִתָּרַם וְדִי אִתַּפְרָשׁ מִדְכַר קֻרְבָּנַיָא מִדִי לְאַהֲרֹן וּמִדִי לִבְנוֹהִי:
@73 וִיהֵי לְאַהֲרֹן וְלִבְנוֹהִי לִקְיַם עָלָם מִן בְּנֵי יִשְׂרָאֵל אֲרֵי אַפְרָשׁוּתָא הוּא וְאַפְרָשׁוּתָא יְהֵי מִן בְּנֵי יִשְׂרָאֵל מִנִכְסַת קוּדְשֵׁיהוֹן אַפְרָשׁוּתְהוֹן קֳדָם יְיָ:
@74 וּלְבוּשֵׁי קוּדְשָׁא דִי לְאַהֲרֹן יְהוֹן לִבְנוֹהִי בַּתְרוֹהִי לְדַכָּאָה בְהוֹן וּלְקָרָבָא בְהוֹן יָת קֻרְבָּנְהוֹן:
@75 שִׁבְעַת יוֹמִין יַלְבֵּשִׁנוּן כַּהֲנָא תְּחוֹתוֹהִי מִבְּנוֹהִי דִי יֵעוֹל לְמַשְׁכַּן זִמְנָא לְשַׁמָשָׁא בְקוּדְשָׁא:
@76 וְיָת דְכַר קֻרְבָּנַיָא תִּסָב וּתְבַשֵׁל יָת בִּסְרֵהּ בַּאֲתַר קַדִישׁ:
@77 וְיֵכוּל אַהֲרֹן וּבְנוֹהִי יָת בְּסַר דִכְרָא וְיָת לַחְמָא דִי בְסַלָא לִתְרַע מַשְׁכַּן זִמְנָא:
@78 וְיֵכְלוּן יָתְהוֹן דִי יִתְכַּפַּר בְּהוֹן לְקָרָבָא יָת קֻרְבָּנְהוֹן לְקַדָשָׁא יָתְהוֹן וְחִלוֹנַי לָא יֵיכוּל אֲרֵי קוּדְשָׁא אִנוּן:
@79 וְאִם יִשְׁתָּאַר מִבְּסַר קֻרְבָּנַיָא וּמִן לַחְמָא עַד צַפְרָא וְתוֹקִיד יָת דְאִשְׁתָּאַר בְּנוּרָא לָא יִתְאֲכֵל אֲרֵי קוּדְשָׁא הוּא:
@80 וְתַעְבֵּד לְאַהֲרֹן וְלִבְנוֹהִי כְּדֵין כְּכֹל דִי פַקֵּדִית יָתָךְ שִׁבְעַת יוֹמִין תְּקָרֵב קֻרְבָּנְהוֹן:
@81 וְתוֹרָא דְחַטָאתָא תַּעְבֵּד לְיוֹמָא עַל כִּפּוּרַיָא וּתְדַכֵּי עַל מַדְבְּחָא בְּכַפָּרוּתָךְ עֲלוֹהִי וּתְרַבֵּי יָתֵהּ לְקַדָשׁוּתֵהּ:
@82 שִׁבְעַת יוֹמִין תְּכַפֵּר עַל מַדְבְּחָא וּתְקַדֵשׁ יָתֵהּ וִיהֵי מַדְבְּחָא קֹדֶשׁ קוּדְשַׁיָא כָּל דְיִקְרַב בְּמַדְבְּחָא יִתְקַדָשׁ:
@83 וְדֵין דִי תַעְבֵּד עַל מַדְבְּחָא אִמְרִין בְּנֵי שְׁנָא תְּרֵין לְיוֹמָא תְּדִירָא:
@84 יָת אִמְרָא חַד תַּעְבֵּד בְּצַפְרָא וְיָת אִמְרָא תִנְיָנָא תַּעְבֵּד בֵּין שִׁמְשַׁיָא:
@85 וְעִסְרוֹנָא סֻלְתָּא דְפִילָא בִמְשַׁח כָּתִישָׁא רַבְעוּת הִינָא וְנִסְכָּא רַבְעוּת הִינָא חַמְרָא לְאִמְרָא חָד:
@86 וְיָת אִמְרָא תִנְיָנָא תַּעְבֵּד בֵּין שִׁמְשַׁיָא כְּמִנְחַת צַפְרָא וּכְנִסְכַּהּ תַּעְבֵּד לַהּ לְאִתְקַּבָּלָא בְרַעֲוָא קֻרְבָּנָא קֳדָם יְיָ:
@87 עֲלָתָא תְדִירָא לְדָרֵיכוֹן בִּתְרַע מַשְׁכַּן זִמְנָא קֳדָם יְיָ דִאֱזַמֵן מֵימְרִי לְכוֹן תַּמָן לְמַלָלָא עִמָךְ תַּמָן:
@88 וֶאֱזַמֵן מֵימְרִי תַמָן לִבְנֵי יִשְׂרָאֵל וְיִתְקַדַשׁ בִּיקָרִי:
@89 וֶאֱקַדֵשׁ יָת מַשְׁכַּן זִמְנָא וְיָת מַדְבְּחָא וְיָת אַהֲרֹן וְיָת בְּנוֹהִי אֱקַדֵשׁ לְשַׁמָשָׁא קֳדָמַי:
@90 וְאַשְׁרֵי שְׁכִנְתִּי בְּגוֹ בְּנֵי יִשְׂרָאֵל וְאֶהֱוֵי לְהוֹן לֶאֱלָהּ:
@91 וְיִדְעוּן אֲרֵי אֲנָא יְיָ אֱלָהֲהוֹן דִי אַפֵּקִית יָתְהוֹן מֵאַרְעָא דְמִצְרַיִם לְאַשְׁרָאָה שְׁכִנְתִּי בֵּינֵיהוֹן אֲנָא יְיָ אֱלָהֲהוֹן:
@92 וְתַעְבֵד מַדְבְּחָא לְאַקְטָרָא עֲלוֹהִי קְטוֹרֶת בּוּסְמַיָא דְאָעֵי שִׁטִין תַּעְבֵּד יָתֵהּ:
@93 אַמְתָא אֻרְכֵּהּ וְאַמְתָא פְתָיֵהּ מְרַבַּע יְהֵי וְתַרְתֵּין אַמִין רוּמֵהּ מִנֵהּ קַרְנוֹהִי:
@94 וְתַחֲפֵי יָתֵהּ דְהַב דְכֵי יָת אִגָרֵהּ וְיָת כָּתְלוֹהִי סְחוֹר סְחוֹר וְיָת קַרְנוֹהִי וְתַעְבֵּד לֵהּ דֵיר דִדְהב סְחוֹר סְחוֹר:
@95 וְתַרְתֵּין עִזְקַן דִדְהַב תַּעְבֶּד לֵהּ מִלְרַע לְדֵירֵהּ עַל תַּרְתֵּין זִוְיָתֵהּ תַּעְבֵּד עַל תְּרֵין סִטְרוֹהִי וִיהֵי לְאַתְרָא לַאֲרִיחַיָא לְמִטַל יָתֵהּ בְּהוֹן:
@96 וְתַעְבֵּד יָת אֲרִיחַיָא דְאָעֵי שִׁטִין וְתַחֲפֵי יָתְהוֹן דַהֲבָא:
@97 וְתִתֵּן יָתֵה קֳדָם פָּרֻכְתָּא דִי עַל אֲרוֹנָא דְסַהֲדוּתָא לִקֳדָם כַּפֻּרְתָּא דִי עַל סַהֲדוּתָא דִי אֲזַמֵן מֵימְרִי לָךְ תַּמָן:
@98 וְיַקְטַר עֲלוֹהִי אַהֲרֹן קְטוֹרֶת בּוּסְמִין בִּצְפַר בִּצְפַר בְּאַתְקָנוּתֵהּ יָת בּוֹצִינַיָא יַסֵקִנַהּ:
@99 וּבְאַדְלָקוּת אַהֲרֹן יָת בּוֹצִינַיָא בֵּין שִׁמְשַׁיָא יַסֵקִנַהּ קְטוֹרֶת בּוּסְמַיָא תְדִירָא קֳדָם יְיָ לְדָרֵיכוֹן:
@100 לָא תַסְקוּן עֲלוֹהִי קְטוֹרֶת בּוּסְמִין נוּכְרָאִין וַעֲלָתָא וּמִנְחָתָא וְנִסְכָּא לָא תְנַסְכוּן עֲלוֹהִי:
@101 וִיכַפֵר אַהֲרֹן עַל קַרְנוֹהִי חֲדָא בְּשַׁתָּא מִדְמָא חַטַאת כִּפּוּרַיָא חֲדָא בְשַׁתָּא יְכַפֵּר עֲלוֹהִי לְדָרֵיכוֹן קֹדֶשׁ קוּדְשִׁין הוּא קֳדָם יְיָ: פפפ:

@1 **ואתה תצוה' זך.** בלי שמרים, כמו ששנינו במנחות (פו א) מגרגרו בראש הזית וכו' : **כתית.** הזיתים היה כותש במכתשת, ואינו טוחנן בריחים, כדי שלא יהו בו שמרים, ואחר שהוציא טפה ראשונה מכניסן לריחים וטוחנן, והשמן השני פסול למנורה וכשר למנחות, שנאמר כתית למאור, ולא כתית למנחות: **להעלות נר תמיד.** מדליק עד שתהא שלהבת עולה מאליה: **תמיד.** כל לילה ולילה קרוי תמיד, כמו שאתה אומר (במדבר כח ו) עולת תמיד, ואינה אלא מיום ליום. וכן במנחת חבתין נאמר (ויקרא ו יג) תמיד, ואינה אלא מחציתה בבקר ומחציתה בערב. אבל תמיד האמור בלחם הפנים משבת לשבת הוא:
@2 **מערב עד בקר.** תן לה מדתה שתהא דולקת מערב עד בקר, ושערו חכמים חצי לוג ללילי טבת הארכין, וכן לכל הלילות, ואם יותר אין בכך כלום:
@3 **ואתה הקרב אליך.** לאחר שתגמר מלאכת המשכן:
@5 **לקדשו לכהנו לי.** לקדשו להכניסו בכהנה על ידי הבגדים שיהא כהן לי, ולשון כהנה שרות הוא, שוריינטריא''ה בלעז :
@6 **חשן.** תכשיט כנגד הלב: **ואפוד.** לא שמעתי ולא מצאתי בברייתא פרוש תבניתו, ולבי אומר לי שהוא חגור לו מאחוריו, רחבו כרוחב גב איש, כמין סינר שקורין פורציינ''ט בלעז שחוגרות השרות כשרוכבות על הסוסים, כך מעשהו מלמטה, שנאמר (שמואל ב ו יד) ודוד חגור אפוד בד, למדנו שהאפוד חגורה היא. ואי אפשר לומר שאין בו אלא חגורה לבדה, שהרי נאמר (ויקרא ח ז) ויתן עליו את האפוד, ואחר כך ויחגור אותו בחשב האפוד, ותרגם אנקלוס בהמין אפודא, למדנו שהחשב הוא החגור, והאפוד שם תכשיט לבדו. ואי אפשר לומר שעל שם שתי הכתפות שבו הוא קרוי אפוד, שהרי נאמר (פסוק כז) שתי כתפות האפוד, למדנו שהאפוד שם לבד, והכתפות שם לבד, והחשב שם לבד. לכך אני אומר שעל שם הסינר של מטה קרוי אפוד, על שם שאופדו ומקשטו בו, כמו שנאמר (ויקרא ח ז) ויאפוד לו בו, והחשב הוא החגור של מעלה המנו, והכתפות קבועות בו. ועוד אומר לי לבי, שיש ראיה שהוא מין לבוש, שתרגם יונתן (שמואל ב' ו יד) ודוד חגור אפוד בד, כרדוט דבוץ. ותרגם כמו כן מעילים, כרדוטין, במעשה תמר אחות אבשלום (שמואל ב יג יח) כי כן תלבשנה בנות המלך הבתולות מעילים: **ומעיל.** הוא כמין חלוק, וכן הכתנת, אלא שהכתונת סמוך לבשרו ומעיל קרוי חלוק עליון: **תשבץ.** עשויין משבצות לנוי, והמשבצות הן כמין גמות העשויות בתכשיטי זהב למושב קביעות אבנים טובות ומרגליות, כמו שנאמר באבני האפוד (פסוק יא) מסבות משבצות זהב, ובלעז קוראין אותו קשטונ''ש : **מצנפת.** כמין כפת כובע שקורין קויפ''א בלעז , שהרי במקום אחר קורא להם (לט כח) מגבעות, ומתרגמנן קובעיא: **ואבנט.** היא חגורה על הכתנת, והאפוד חגורה על המעיל, כמו שמצינו בסדר לבישתן (ויקרא ח ז) ויתן עליו את הכתנת ויחגור אותו באבנט וילבש אותו את המעיל ויתן עליו את האפוד: **בגדי קדש.** מתרומה המקדשת לשמי יעשו אותם:
@7 **והם יקחו.** אותם חכמי לב שיעשו הבגדים, יקבלו מן המתנדבים את הזהב ואת התכלת לעשות מהן את הבגדים:
@8 **ועשו את האפוד.** אם באתי לפרש מעשה האפוד והחשן על סדר המקראות, הרי פרושן פרקים פרקים, וישגה הקורא בצרופן, לכך אני כותב מעשיהם כמות שהוא, למען ירוץ הקורא בו, ואחר כך אפרש על סדר המקראות. האפוד עשוי כמין סינר של נשים רוכבות סוסים, וחוגר אותו מאחוריו כנגד לבו למטה מאציליו, רחבו כמדת רוחב גבו של אדם ויותר ומגיע עד עקביו, והחשב מחבר בראשו על פני רחבו מעשה אורג, ומאריך לכאן ולכאן כדי להקיף ולחגור בו, והכתפות מחברות בחשב אחד לימין ואחד לשמאל, מרוחקות זו מזו שעור הבדלת כתפים, מאחורי הכהן לשני קצות רחבו של סינר, וכשזוקפן עומדות לו על שני כתפיו, והן כמין שתי רצועות עשויות ממין האפוד, ארכות כדי שעור לזקפן אצל צוארו מכאן ומכאן, ונקפלות לפניו למטה מכתפיו מעט, ואבני השהם קבועות בהם, אחת על כתף ימין ואחת על כתף שמאל, והמשבצות נתונות בראשיהם לפני כתפיו, ושתי עבותות הזהב תחובות בשתי טבעות שבחשן בשני קצות רחבו העליון, אחת לימין ואחת לשמאל, ושני ראשי השרשרת [הימנית] תקועין במשבצות לימין, וכן שני ראשי השרשרת השמאלית תקועין במשבצות שבכתף שמאל, נמצא החושן תלוי במשבצות האפוד על לבו מלפניו. ועוד שתי טבעות בשני קצות החשן בתחתיתו וכנגדם שתי טבעות בשתי כתפות האפוד מלמטה בראשו התחתון המחבר בחשב, טבעות החשן אל מול טבעות האפוד שוכבים זה על זה ומרכסן בפתיל תכלת תחוב בטבעות האפוד והחשן, שיהא תחתית החשן דבוק לחשב האפוד ולא יהא נד ונבדל, הולך וחוזר: **זהב תכלת וארגמן תולעת שני ושש משזר.** חמשת מינים הללו שזורין בכל חוט וחוט היו מרדדין את הזהב כמין טסין דקין וקוצצין פתילים מהם, וטווין אותן חוט של זהב עם ששה חוטים של תכלת, וחוט של זהב עם ששה חוטין של ארגמן, וכן בתולעת שני, וכן בשש, שכל המינין חוטן כפול ששה, וחוט של זהב עם כל אחד ואחד, ואחר כך שוזר את כלם כאחד, נמצא חוטן כפול עשרים ושמונה. וכן מפורש במסכת יומא (עב א) , ולמד מן המקרא הזה (שמות לט ג) וירקעו את פחי הזהב וקצץ פתילים לעשות, את פתילי הזהב, בתוך התכלת ובתוך הארגמן וגו' , למדנו שחוט של זהב שזור עם כל מין ומין: **מעשה חשב.** כבר פרשתי (שמות כו א) שהוא אריגת שתי קירות שאין צורות שני עבריה דומות זו לזו:
@9 **שתי כתפות** וגו' **.** הסינר מלמטה, וחשב האפוד היא החגורה וצמודה לו מלמעלה דגמת סינר הנשים, ומגבו של כהן היו מחברות בחשב. שתי חתכות כמין שתי רצועות רחבות, אחת כנגד כל כתף וכתף, וזוקפן על שתי כתפותיו עד שנקפלות לפניו כנגד החזה, ועל ידי חבורן לטבעות החשן נאחזין מלפניו כנגד לבו שאין נופלות, כמו שמפורש בענין, והיו זקופות והולכות כנגד כתפיו, ושתי אבני השהם קבועות בהן, אחת בכל אחת: **אל שני קצותיו.** אל רחבו של אפוד, שלא היה רחבו אלא כנגד גבו של כהן, וגבהו עד כנגד האצילים שקורין קודי''ש בלעז [מרפקים] שנאמר (יחזקאל מד יח) לא יחגרו ביזע, אין חוגרין במקום זיעה, לא למעלה מאציליהם ולא למטה ממתניהם, אלא כנגד אציליהם: **וחבר.** האפוד עם אותן שתי כתפות האפוד, יחבר אותם במחט למטה בחשב, ולא יארגם עמו, אלא אורגם לבדם ואחר כך מחברם:
@10 **וחשב אפדתו.** וחגור שעל ידו הוא מאפדו ומתקנהו לכהן ומקשטו: **אשר עליו.** למעלה בשפת הסינר, היא החגורה: **כמעשהו.** כאריגת הסינר מעשה חושב ומחמשת מינים, כך אריגת החשב מעשה חושב ומחמשת מינין: **ממנו יהיה.** עמו יהיה ארוג, ולא יארגנו לבד ויחברנו:
@12 **כתולדתם.** כסדר שנלדו ראובן שמעון לוי יהודה דן נפתלי, על האחת, ועל השניה גד אשר יששכר זבולן יוסף בנימין מלא, שכן הוא כתוב במקום תולדתו, עשרים וחמש אותיות בכל אחת ואחת:
@13 **מעשה חרש אבן.** מעשה אמן של אבנים. חרש זה דבוק הוא לתבה שלאחריו, ולפיכך הוא נקוד פתח בסופו, וכן (ישעיה מד יג) חרש עצים נטה קו, חרש של עצים. וכן (ישעיה מד יב) חרש ברזל מעצד, כל אלה דבוקים ופתוחים: **פתוחי חתם.** כתרגומו כתב מפרש כגלף דעזקא, חרוצות האותיות בתוכן, כמו שחורצין חותמי טבעות שהם לחתום אגרות, כתב נכר ומפרש: **על שמות.** כמו בשמות: **מסבת משבצות.** מוקפות האבנים במשבצות זהב, שעושה מושב האבן בזהב כמין גומא למדת האבן ומשקיעה במשבצות, נמצאת המשבצת סובבת את האבן סביב, ומחבר המשבצות בכתפות האפוד:
@14 **לזכרון.** שיראה הקדוש ברוך הוא השבטים כתובים לפניו ויזכור צדקתם:
@15 **ועשית משבצות.** מעוט משבצות שתים, ולא פרש לך עתה בפרשה זו אלא מקצת צרכן, ובפרשת החושן גומר לך פרושן:
@16 **שרשרת זהב.** שלשלאות: **מגבלות.** לסוף גבול החשן תעשה אותם: **מעשה עבות.** מעשה קליעת חוטין, ולא מעשה נקבים וכפלים, כאותן שעושין לבורות, אלא כאותן שעושין לערדסקאות, שקורין אינצינשייר''ש בלעז [כלי קטורת] : **ונתת את שרשרת.** של עבותות העשויות מעשה עבות על המשבצות הללו. ולא זה הוא מקום צואת עשיתן של שרשרות, ולא צואת קביעתן, ואין תעשה האמור כאן לשון צווי, ואין ונתתה האמור כאן לשון צווי, אלא לשון עתיד, כי בפרשת החשן חוזר ומצוה על עשיתן ועל קביעתן, ולא נכתב כאן אלא להודיע מקצת צורך המשבצות שצוה לעשות עם האפוד, וכתב לך זאת לומר לך המשבצות הללו יזקקו לך לכשתעשה שרשרות מגבלות על החשן, תתנם על המשבצות הללו:
@17 **חשן משפט.** שמכפר על קלקול הדין. דבר אחר משפט, שמברר דבריו והבטחתו אמת, דיריישנימינ''ט בלעז . שהמשפט משמש שלש לשונות דברי טענות הבעלי דינים, וגמר הדין, ועונש הדין, אם עונש מיתה, אם עונש מכות, אם עונש ממון, וזה משמש לשון ברור דברים, שמפרש ומברר דבריו: **כמעשה אפוד.** מעשה חושב ומחמשת מינין:
@18 **זרת ארכו וזרת רחבו.** כפול ומוטל לו לפניו כנגד לבו, שנאמר (פסוק ל) והיו על לב אהרן, תלוי בכתפות האפוד, הבאות מאחוריו על כתפיו ונקפלות ויורדות לפניו מעט, והחשן תלוי בהן בשרשרות וטבעות, כמו שמפורש בענין:
@19 **ומלאת בו.** על שם שהאבנים ממלאות גמות המשבצות המתקנות להן, קורא אותן בלשון מלאים:
@22 **משבצים זהב.** יהיו הטורים במלואתם, מקפים משבצות זהב בעומק שעור שיתמלא בעובי האבן, זהו לשון במלואתם, כשיעור מלוי עביין של אבנים יהיה עומק המשבצות לא פחות ולא יותר:
@23 **איש על שמו.** כסדר תולדותם סדר האבנים, אודם לראובן, פטדה לשמעון, וכן כלם:
@24 **על החשן.** בשביל החשן, לקבעם בטבעותיו, כמו שמפורש למטה בענין: **שרשת.** לשון שרשי אילן המאחיזין לאילן להאחז ולהתקע בארץ, אף אלו יהיו מאחיזין לחשן, שבהם יהיה תלוי באפוד, והן שתי שרשרות האמורות למעלה (פסוק יד) בענין המשבצות. ואף שרשרות פתר מנחם בן סרוק לשון שרשים, ואמר שהרי''ש יתרה, כמו מ''ם שבשלשום, ומ''ם שבריקם. ואיני רואה את דבריו, אלא שרשרת בלשון עברית, כשלשלת בלשון משנה: **גבלת.** הוא מגבלות האמור למעלה (פסוק יד) שתתקעם בטבעות, שיהיו בגבול החשן, וכל גבול לשון קצה, אשומיי''ל בלעז : **מעשה עבות.** מעשה קליעה:
@25 **על החשן.** לצורך החושן, כדי לקבעם בו. ולא יתכן לומר שתהא תחלת עשיתן עליו, שאם כן מה הוא שחוזר ואומר ונתת את שתי הטבעות, והלא כבר נתונים בו, היה לו לכתוב בתחלת המקרא ועשית על קצות החשן שתי טבעות זהב, ואף בשרשרות צריך אתה לפתור כן: **על שני קצות החשן.** לשתי פאות שכנגד הצואר, לימנית ולשמאלית הבאים מול כתפות האפוד:
@26 **ונתתה את שתי עבתת הזהב.** הן הן שרשרות גבלות הכתובות למעלה (פסוק כב) ולא פרש מקום קבוען בחשן, עכשיו מפרש לך שיהא תוחב אותן בטבעות, ותדע לך שהן הן הראשונות, שהרי בפרשת אלה פקודי לא הכפלו:
@27 **ואת שתי קצות.** של שתי העבותות שני ראשיהם שלכל אחת: **תתן על שתי המשבצות.** הן הכתובות למעלה (פסוק יד) בין פרשת החשן ופרשת האפוד, ולא פרש את צרכן ואת מקומן, עכשיו מפרש שיתקע בהן ראשי העבותות התחובות בטבעות [בראשי] החשן לימין ולשמאל אצל הצואר, שני ראשי השרשרת הימנית תוקע במשבצות של ימין, וכן בשל שמאל שני ראשי שרשרות השמאלית: **ונתתה.** המשבצות: **על כתפות האפוד.** אחת בזו ואחת בזו, נמצאו כתפות האפוד מחזיקין את החשן שלא יפל, ובהן הוא תלוי, ועדין שפת החשן התחתונה הולכת ובאה ונוקשת על כרסו, ואינה דבוקה לו יפה, לכך הצרך עוד שתי טבעות לתחתיתו, כמו שמפרש והולך: **אל מול פניו.** של אפוד, שלא יתן המשבצות בעבר הכתפות שכלפי המעיל, אלא בעבר העליון שכלפי החוץ, והוא קרוי מול פניו של אפוד, כי אותו עבר שאינו נראה אינו קרוי פנים:
@28 **על שני קצות החשן.** הן שתי פאותיו התחתונות לימין ולשמאל: **על שפתו אשר אל עבר האפד ביתה.** הרי לך שני סימנין האחד שיתנם בשני קצות של תחתיתו שהוא כנגד האפוד, שעליונו אינו כנגד האפוד, שהרי סמוך לצואר הוא, והאפוד נתון על מתניו, ועוד נתן סימן שלא יקבעם בעבר החשן שכלפי החוץ, אלא בעבר שכלפי פנים שנאמר ביתה, ואותו העבר הוא לצד האפוד, שחשב האפוד חוגרו הכהן ונקפל הסינר לפני הכהן על מתניו, וקצת כרסו מכאן ומכאן עד כנגד קצות החשן, וקצותיו שוכבין עליו:
@29 **על שתי כתפות האפוד מלמטה.** שהמשבצות נתונות בראשי כתפות האפוד העליונים הבאים על כתפיו כנגד גרונו, ונקפלות ויורדות לפניו, והטבעות צוה לתן בראשן השני, שהוא מחבר לאפוד, והוא שנאמר לעמת מחברתו, סמוך למקום חבורן באפוד למעלה מן החגורה מעט, שהמחברת לעמת החגורה, ואלו נתונים מעט בגובה זקיפת הכתפות, הוא שנאמר ממעל לחשב האפוד, והן כנגד סוף החשן, ונותן פתיל תכלת באותן הטבעות ובטבעות החשן, ורוכסן באותן פתילין לימין ולשמאל, שלא יהא תחתית החושן הולך לפנים וחוזר לאחור ונוקש על כרסו, ונמצא מישב על המעיל יפה: **ממול פניו.** בעבר החיצון:
@30 **וירכסו.** לשון חבור, וכן (תהלים לא כא) מרכסי איש, חבורי חבלי רשעים, וכן (ישעיה מ ד) והרכסים לבקעה, הרים הסמוכים זה לזה שאי אפשר לירד לגיא שביניהם אלא בקושי גדול, שמתוך סמיכתן הגיא זקופה ועמוקה, יהיו לבקעת מישור ונוחה לילך: **להיות על חשב האפוד.** להיות החשן דבוק אל חשב האפוד: **ולא יזח.** לשון נתוק, ולשון ערבי הוא, כדברי דונש בן לברט:
@32 **את האורים ואת התמים.** הוא כתב שם המפורש, שהיה נותנו בתוך כפלי החשן, שעל ידו הוא מאיר דבריו ומתמם את דבריו. ובמקדש שני היה החשן, שאי אפשר לכהן גדול להיות מחסר בגדים, אבל אותו השם לא היה בתוכו, ועל שם אותו הכתב הוא קרוי משפט, שנאמר (במדבר כז כא) ושאל לו במשפט האורים: **את משפט בני ישראל.** דבר שהם נשפטים ונוכחים על ידו אם לעשות דבר או לא לעשות. ולפי מדרש אגדה שהחשן מכפר על מעותי הדין, נקרא משפט על שם סליחת המשפט:
@33 **את מעיל האפוד.** שהאפוד נתון עליו לחגורה: **כליל תכלת.** כלו תכלת, שאין מין אחר מעורב בו:
@34 **והיה פי ראשו.** פי המעיל שבגבהו הוא פתיחת בית הצואר: **בתוכו.** כתרגומו כפיל לגויה, כפול לתוכו להיות לו לשפה כפילתו, והיה מעשה אורג ולא במחט: **כפי תחרא.** למדנו שהשריונים שלהם פיהם כפול לתוכן: **לא יקרע.** כדי שלא יקרע, והקורעו עובר בלאו, שזה ממנין לאוין שבתורה, וכן (פסוק כח) ולא יזח החשן, וכן (שמות כה טו) לא יסורו ממנו. הנאמר בבדי הארון:
@35 **רמוני.** עגולים וחלולים היו כמין רמונים העשויים כביצת תרנגולת: **ופעמוני זהב.** זגין עם ענבלין שבתוכם: **בתוכם סביב.** ביניהם סביב, בין שני רמונים פעמון אחד דבוק ותלוי בשולי המעיל:
@36 **פעמון זהב ורמון פעמון זהב ורמון.** אצלו:
@37 **ולא ימות.** מכלל לאו אתה שומע הן, אם יהיו לו לא יתחיב מיתה, הא אם יכנס מחסר אחד מן הבגדים הללו חיב מיתה בידי שמים:
@38 **ציץ.** כמין טס של זהב היה, רוחב שתי אצבעות, מקיף על המצח מאוזן לאוזן:
@39 **על פתיל תכלת.** ובמקום אחר הוא אומר (שמות לט לא) ויתנו עליו פתיל תכלת, ועוד כתיב כאן והיה על המצנפת, ולמטה הוא אומר (פסוק לח) והיה על מצח אהרן, ובשחיטת קדשים שנינו (זבחים יט א) שערו היה נראה בין ציץ למצנפת, ששם מניח תפלין, למדנו שהמצנפת למעלה בגובה הראש ואינה עמוקה לכנס בה כל הראש עד המצח, והציץ מלמטה, והפתילים היו בנקבים ותלויין בו בשני ראשים ובאמצעיתו ששה בשלושה מקומות הללו, פתיל מלמעלה, אחד מבחוץ, ואחד מבפנים כנגדו, וקושר ראשי הפתילים מאחורי העורף שלשתן, ונמצאו בין אורך הטס ופתילי ראשו מקיפין את הקדקד, ופתיל האמצעי שבראשו קשור עם ראשי השנים, הולך על פני רוחב הראש מלמעלה, ונמצא עשוי כמין כובע, ועל פתיל האמצעי הוא אומר והיה על המצנפת, והיה נותן הציץ על ראשו כמין כובע על המצנפת, והפתיל האמצעי מחזיקו שאינו נופל, והטס תלוי כנגד מצחו, ונתקימו כל המקראות פתיל על הציץ, וציץ על הפתיל, והפתיל על המצנפת מלמעלה:
@40 **ונשא אהרן.** לשון סליחה, ואף על פי כן אינו זז ממשמעו, אהרן נושא את המשא שלעון, נמצא מסלק העון מן הקדשים: **את עון הקדשים.** לרצות על הדם ועל החלב שקרבו בטומאה, כמו ששנינו (פסחים טז א) אי זה עון הוא נושא, אם עון פגול, הרי כבר נאמר (ויקרא יט ז) לא ירצה, ואם עון נותר, הרי נאמר (ויקרא ז יח) לא יחשב, ואין לומר שיכפר על עון הכהן שהקריב טמא, שהרי עון הקדשים נאמר, ולא עון המקריבים, הא אינו מרצה אלא להכשיר הקרבן: **והיה על מצחו תמיד.** אי אפשר לומר שיהא על מצחו תמיד, שהרי אינו עליו אלא בשעת העבודה, אלא תמיד לרצות להם, אפלו אינו על מצחו, שלא היה כהן גדול עובד באותה שעה. ולדברי האומר (יומא ז ב) עודהו על מצחו מכפר ומרצה, ואם לאו אינו מרצה, נדרש על מצחו תמיד, מלמד שמשמש בו בעודו על מצחו, שלא יסיח דעתו ממנו:
@41 **ושבצת.** עשה אותה משבצות משבצות, וכלה של שש:
@42 **ולבני אהרן תעשה כתנת.** ארבעה בגדים הללו ולא יותר כתנת, ואבנט, ומגבעות היא מצנפת, ומכנסים הכתובים למטה בפרשה (פסוק מב) :
@43 **והלבשת אתם את אהרן.** אותם האמורים באהרן חשן ואפוד ומעיל וכתונת תשבץ, מצנפת ואבנט וציץ ומכנסים, הכתובים למטה בכלם: **ואת בניו אתו.** אותם הכתובים בהם: **ומשחת אותם.** את אהרן ואת בניו בשמן המשחה: **ומלאת את ידם.** כל מלוי ידים לשון חנוך, כשהוא נכנס לדבר להיות מחזק בו מאותו יום והלאה הוא מלוי, ובלשון לעז כשממנין אדם על פקידת דבר, נותן השליט בידו בית יד של עור שקורין גנ''ט בלעז [כפפה] , ועל ידו הוא מחזיקו בדבר, וקורין לאותו מסירה ריוישטי''ר בלעז [להסמיך] והוא מלוי ידים:
@44 **ועשה להם.** לאהרן ולבניו: **מכנסי בד.** הרי שמונה בגדים לכהן גדול, וארבעה לכהן הדיוט:
@45 **והיו על אהרן.** כל הבגדים האלה על אהרן הראויין לו: **ועל בניו.** האמורים בהם: **בבאם אל אהל מועד.** להיכל, וכן למשכן: **ומתו.** הא למדת, שהמשמש מחסר בגדים במיתה: **חקת עולם לו.** כל מקום שנאמר חקת עולם, הוא גזרה מיד ולדורות, לעכב בו:
@46 **לקח.** כמו קח, ושתי גזרות הן, אחת של קיחה, ואחת של לקיחה, ולהן פתרון אחד: **פר אחד.** לכפר על מעשה העגל שהוא פר:
@47 **ולחם מצות וחלת מצת ורקיקי מצות.** הרי אלו שלשה מינין רבוכה, וחלות ורקיקים לחם מצות, היא הקרויה למטה בענין (פסוק כג) חלת לחם שמן, על שם שנותן שמן ברבוכה כנגד החלות והרקיקין, וכל המינין באים עשר עשר חלות: **בלולת בשמן.** כשהן קמח יוצק בהן שמן ובוללן: **משחים בשמן.** אחר אפייתן מושחן כמין כי יונית, שהיא עשויה כנו''ן שלנו:
@48 **והקרבת אתם.** אל חצר המשכן ביום הקמתו:
@49 **ורחצת.** זו טבילת כל הגוף:
@50 **ואפדת.** קשט ותקן החגורה והסינר סביבותיו:
@51 **נזר הקדש.** זה הציץ: **על המצנפת.** כמו שפרשתי למעלה (שמות כח לז) על ידי הפתיל האמצעי ושני פתילין שבראשו הקשורין שלשתן מאחורי העורף, הוא נותנו על המצנפת כמין כובע:
@52 **ומשחת אותו.** אף משיחה זו כמין כי יונית, נותן שמן על ראשו ובין ריסי עיניו ומחברן באצבעו:
@54 **והיתה להם.** מלוי ידים זה לכהנת עולם: **ומלאת.** על ידי הדברים האלה: **יד אהרן ויד בניו.** במלוי ופקדת הכהונה:
@56 **פתח אהל מועד.** בחצר המשכן שלפני הפתח:
@57 **על קרנות.** למעלה בקרנות ממש: **ואת כל הדם.** שירי הדם: **אל יסוד המזבח.** כמין בליטת בית קבול עשוי לו סביב סביב לאחר שעלה אמה מן הארץ:
@58 **החלב המכסה את הקרב.** הוא הקרום שעל הכרס שקורין טייל''א : **ואת היתרת.** הוא טרפשא דכבדא שקורין איבדי''ש [סרעפת] : **על הכבד.** אף מן הכבד יטול עמה:
@59 **תשרף באש.** לא מצינו חטאת חיצונה נשרפת אלא זו:
@61 **וזרקת.** בכלי, אוחז במזרק וזורק כנגד הקרן כדי שיראה לכאן ולכאן, ואין קרבן טעון מתנה באצבע אלא חטאת בלבד, אבל שאר זבחים אינן טעונין קרן ולא אצבע, שמתן דמם מחצי המזבח ולמטה, ואינו עולה בכבש אלא עומד בארץ וזורק: **סביב.** כך מפורש בשחיטת קדשים (זבחים נב ב) שאין סביב אלא שתי מתנות שהן ארבע, האחת בקרן זוית זו, והאחת בקרן שכנגדה באלכסון, וכל מתנה נראית בשני צדי הקרן אלך ואלך, נמצא הדם נתן בארבע רוחות סביב, לכך קרוי סביב:
@62 **על נתחיו.** עם נתחיו, מוסף על שאר הנתחים:
@63 **ריח ניחוח.** נחת רוח לפני, שאמרתי ונעשה רצוני: **אשה.** לשון אש, והיא הקטרת איברים שעל האש:
@65 **תנוך.** הוא הסחוס האמצעי שבתוך האזן שקורין טנדרו''ם : **בהן ידם.** הגדל ובפרק האמצעי:
@67 **החלב.** זה חלב הדקים או הקיבה: **והאליה.** מן הכליות ולמטה, כמו שמפורש בויקרא (ג ט) שנאמר לעמת העצה יסירנה, מקום שהכליות יועצות, ובאמורי הפר לא נאמר אליה, שאין אליה קריבה אלא בכבש וכבשה ואיל, אבל שור ועז אין טעונים אליה: **ואת שוק הימין.** לא מצינו הקטרה בשוק הימין עם האמורים אלא זו בלבד: **כי איל מלאים הוא.** שלמים, לשון שלמות שמשלם בכל. מגיד הכתוב שהמלואים שלמים, שמשימים שלום למזבח ולעובד העבודה ולבעלים, לכך אני מצריכו החזה להיות לו לעובד העבודה למנה, וזהו משה ששמש במלואים, והשאר אכלו אהרן ובניו שהם בעלים, כמפורש בענין:
@68 **וככר לחם.** מן החלות: **וחלת לחם שמן.** ממין הרבוכה: **ורקיק.** מן הרקיקין, אחד מעשרה שבכל מין ומין ולא מצינו תרומת לחם הבא עם זבח נקטרת אלא זו בלבד, שתרומת לחמי תודה ואיל נזיר נתונה לכהנים עם חזה ושוק, ומזה לא היה למשה למנה אלא חזה בלבד:
@69 **על כפי אהרן** וגו' **והנפת.** שניהם עסוקים בתנופה, הבעלים והכהן. הא כיצד, כהן מניח ידו תחת יד הבעלים ומניף, ובזה היו אהרן ובניו בעלים, ומשה כהן: **תנופה.** מוליך ומביא למי שארבע רוחות העולם שלו, ותנופה מעכבת רוחות רעות. תרומה מעלה ומוריד למי שהשמים וארץ שלו, ומעכבת טללים רעים:
@70 **על העולה.** על האיל הראשון שהעלית עולה: **לריח ניחוח.** לנחת רוח למי שאמר ונעשה רצונו: **אשה.** לאש נתן: **לה'.** לשמו של מקום:
@72 **וקדשת את חזה התנופה ואת שוק התרומה** וגו' **.** קדשם לדורות, להיות נוהגת תרומתם והנפתם כחזה ושוק של שלמים, אבל לא להקטרה, אלא והיה לאהרן ולבניו לאכול: **תנופה.** לשון הולכה והבאה, וינטילי''ר בלעז : **הורם.** לשון מעלה ומוריד:
@73 **לחק עולם מאת בני ישראל.** שהשלמים לבעלים, ואת החזה ואת השוק יתנו לכהן: **כי תרומה הוא.** החזה ושוק הזה:
@74 **לבניו אחריו.** למי שבא בגדלה אחריו: **למשחה.** להתגדל בהם, שיש משיחה שהיא לשון שררה, כמו (במדבר יח ח) לך נתתים למשחה, (תהלים קה טו) אל תגעו במשיחי: **ולמלא בם את ידם.** על ידי הבגדים הוא מתלבש בכהנה גדולה:
@75 **שבעת ימים.** רצופין: **ילבשם הכהן.** אשר יקום מבניו תחתיו לכהנה גדולה, כשימנוהו להיות כהן גדול: **אשר יבא אל אהל מועד.** אותו כהן המוכן לכנס לפני ולפנים ביום הכפורים, וזהו כהן גדול, שאין עבודת יום הכפורים כשרה אלא בו: **תחתיו מבניו.** מלמד שאם יש לו לכהן גדול בן ממלא את מקומו, ימנוהו כהן גדול תחתיו: **הכהן תחתיו מבניו.** מכאן ראיה כל לשון כהן לשון פועל עובד ממש, לפיכך נגון תביר נמשך לפניו:
@76 **במקום קדוש.** בחצר אהל מועד, שהשלמים הללו קדשי קדשים היו:
@77 **פתח אהל מועד.** כל החצר קרוי כן:
@78 **ואכלו אתם.** אהרן ובניו, לפי שהם בעליהם: **אשר כפר בהם.** כל זרות ותיעוב: **למלא את ידם.** באיל ולחם הללו: **לקדש אתם.** שעל ידי המלאים הללו נתמלאו ידיהם ונתקדשו לכהנה: **כי קדש הם.** קדשי קדשים, ומכאן למדנו אזהרה לזר האוכל קדש קדשים, שנתן המקרא טעם לדבר משום דקדש הם:
@80 **ועשית לאהרן ולבניו ככה.** שנה הכתוב וכפל לעכב, שאם חסר דבר אחד מכל האמור בענין, לא נתמלאו ידיהם להיות כהנים ועבודתם פסולה: **אתכה.** כמו אותך: **שבעת ימים תמלא** וגו' **.** בענין הזה ובקרבנות הללו בכל יום:
@81 **על הכפרים.** בשביל הכפורים, לכפר על המזבח מכל זרות ותיעוב. ולפי שנאמר (פסוק לה) שבעת ימים תמלא ידם, אין לי אלא דבר הבא בשבילם, כגון האילים והלחם, אבל הבא בשביל המזבח, כגון פר שהוא לחטוי המזבח, לא שמענו, לכך הצרך מקרא זה. ומדרש תורת כהנים אומר כפרת המזבח הצרך, שמא התנדב איש דבר גזל במלאכת המשכן והמזבח: **וחטאת.** ותדכי, לשון מתנת דמים הנתונים באצבע קרוי חטוי: **ומשחת אתו.** בשמן המשחה וכל המשיחות כמין כי יונית:
@82 **והיה המזבח קדש.** ומה היא קדשתו, כל הנגע במזבח יקדש, אפלו קרבן פסול שעלה עליו, קדשו המזבח להכשירו שלא ירד. מתוך שנאמר כל הנגע במזבח יקדש, שומע אני בין ראוי בין שאינו ראוי, כגון דבר שלא היה פסולו בקדש, כגון הרובע והנרבע ומקצה ונעבד והטרפה וכיוצא בהן, תלמוד לומר וזה אשר תעשה, הסמוך אחריו, מה עולה ראויה אף כל ראוי, שנראה לו כבר ונפסל משבא לעזרה, כגון הלן והיוצא והטמא ושנשחט במחשבת חוץ לזמנו וחוץ למקומו וכיוצא בהן:
@85 **ועשרון סולת.** עשירית האיפה, ארבעים ושלש ביצים וחמש ביצה: **בשמן כתית.** לא לחובה נאמר כתית אלא להכשיר, לפי שנאמר (לעיל כז כ) כתית למאור, ומשמע למאור ולא למנחות, יכול לפסלו למנחות, תלמוד לומר כאן כתית, ולא נאמר (שמות כז כ) כתית למאור אלא למעט מנחות שאין צריך כתית, שאף הטחון בריחים כשר בהן: **רבע ההין.** שלשה לוגין: **ונסך.** לספלים, כמו ששנינו במסכת סכה (מח א) שני ספלים של כסף היו בראש המזבח, ומנקבים כמין שני חטמין דקים, נותן היין לתוכו והוא מקלח ויוצא דרך החוטם ונופל על גג המזבח, ומשם יורד לשיתין במזבח בית עולמים, ובמזבח הנחשת יורד מן המזבח לארץ:
@86 **לריח ניחח.** על המנחה נאמר, שמנחת נסכים כלה כליל, וסדר הקרבתן האיברים בתחלה ואחר כך המנחה, שנאמר (ויקרא כג לז) עולה ומנחה:
@87 **תמיד.** מיום אל יום, ולא יפסיק יום בנתים: **אשר אועד לכם.** כשאקבע מועד לדבר אליך שם אקבענו לבא. ויש מרבותינו למדים מכאן, שמעל מזבח הנחשת היה הקדוש ברוך הוא מדבר עם משה משהוקם המשכן, ויש אומרים מעל הכפרת, כמו שנאמר (שמות כה כב) ודברתי אתך מעל הכפורת, ואשר אועד לכם האמור כאן אינו אמור על המזבח, אלא על אהל מועד הנזכר במקרא:
@88 **ונועדתי שמה.** אתועד עמם בדבור, כמלך הקובע מקום מועד לדבר עם עבדיו שם: **ונקדש.** המשכן: **בכבודי.** שתשרה שכינתי בו. ומדרש אגדה אל תקרי בכבודי, אלא [במכבדי] , במכבדים שלי, כאן רמז לו מיתת בני אהרן ביום הקמתו, וזהו שאמר משה (ויקרא י ג) הוא אשר דבר ה' לאמר בקרובי אקדש, והיכן דבר, ונקדש בכבודי:
@91 **לשכני בתוכם.** על מנת לשכון אני בתוכם:
@92 **מקטר קטרת.** להעלות עליו קיטור עשן סמים:
@94 **את גגו.** זה היה לו גג, אבל מזבח העולה לא היה לו גג, אלא ממלאים חללו אדמה בכל חניתן: **זר זהב.** סימן הוא לכתר כהנה:
@95 **צלעותיו.** כאן הוא לשון זויות, כתרגומו, לפי שנאמר על שני צדיו, על שתי זויותיו שבשני צדיו: **והיה.** מעשה הטבעות האלה: **לבתים לבדים.** לכל בית תהיה הטבעת לבד:
@97 **לפני הפרכת.** שמא תאמר משוך מכנגד הארון לצפון או לדרום, תלמוד לומר לפני הכפרת, מכון כנגד הארון מבחוץ:
@98 **בהיטיבו.** לשון נקוי הבזכין של מנורה מדשן הפתילות שנשרפו בלילה, והיה מטיבן בכל בקר ובקר: **הנרות.** לוצי''ש בלעז [מנורות] וכן כל נרות האמורות במנורה, חוץ ממקום שנאמר שם העלאה, שהוא לשון הדלקה:
@99 **ובהעלות.** כשידליקם להעלות להבתן: **יקטירנה.** בכל יום פרס מקטיר שחרית ופרס מקטיר בין הערבים:
@100 **לא תעלו עליו.** על מזבח זה: **קטרת זרה.** שום קטורת של נדבה. כלן זרות לו חוץ מזו: **ועולה ומנחה.** ולא עולה ומנחה, עולה של בהמה ועוף, ומנחה היא של מין לחם:
@101 **וכפר אהרן.** מתן דמים: **אחת בשנה.** ביום הכפורים, הוא שנאמר באחרי מות (ויקרא טז יח) ויצא אל המזבח אשר לפני ה' וכפר עליו: **חטאת הכפורים.** הם פר ושעיר של יום הכפורים המכפרים על טומאת מקדש וקדשיו: **קדש קדשים.** המזבח מקדש לדברים הללו בלבד ולא לעבודה אחרת:
@102 **אתה בן אדם הגד את בית ישראל את הבית ויכלמו מעונותיהם.** בהראותי למו חסדי שאיני מואסם בעונם, מצאתי. ומדדו את תכנית. ומדדו על ידיך שאתה מורה את תוכן חשבון הבנין:
@103 **ואם נכלמו.** שיתביישו ויכבשו פניהם מכל אשר עשו אז הודע אותם את מה שאני עתיד לעשות להם: **צורת הבית.** וגבול הבנין היאך הוא מלפניו ועד אחריו סדורים לארבע רוחותיו: **ותכונתו.** חשבון תאיו ולשכותיו: **וכל צורותיו.** כרובים ותמורי' ואילי' ואילמים, מצאתי: **וכל צורותיו.** בתרא לא פורש: **וישמרו.** ילמדו ענייני המדות מפיך שידעו לעשותם לעת קץ, מצאתי, ראויה היתה ביאה שנייה של עזרא כביאה ראשונה של יהושע לבא בזרוע ובנס כדדרשינן עד יעבור ובנין זה מאז היה ראוי להם כשעלו מן הגולה לגאולת עולם אלא שגרם החטא שלא היתה תשובתם הוגנת על מנת שלא לחטוא ויצאו ברשות כורש ובנו לעצמן ויש אומרים בבבל נכשלו בנכריות:
@105 **ואלה מדות המזבח.** שמפרש למטה ארבע עשרה אורך בארבע עשרה רחב: **באמות אמה אמה וטופח.** באמה בת ששה שהיא אמה וטופח באמה בת חמשה: **וחיק האמה.** אבל היסוד שלא נמדד באמה של חול שהיא בת ה' חיק לשון חיקויו קביעות והיא היסוד האמה אמת חול ולא אמה וטופח שהיא אמה בת ששה וכן שנינו במנחות שהיסוד והסובב והקרנות נמדדין באמה בת חמשה: **וחיק האמה.** זה היסוד: **ואמה רוחב.** זה הסובב: **וגבולה אל שפתה סביב זרת האחד.** אלו הקרנות זרת אחד מאמצעיתו מדדו זרת לכל רוח הרי אמה על אמה: **וזה גב המזבח.** ובאמה זו היה נמדד גב מזבח הזהב אמה ארכו ואמה רחבו רבוע כך מפורש בעירובין ובמנחות ( דף צד ) מפורש יותר לפי החשבון חיק האמה בגובהה עלה אמה ואמה רחב כנסה כניסת הסובב אמה בת חמשה אבל עלייתו ששנינו עלה ה' וכנס אמה אינו באמה בת חמשה. וגבולה אל שפתה. הקרנות בין לרחבן בין לגבהן באמה בת חמשה:
@106 **ומחיק הארץ.** מן היסוד מקרקע הארץ: **עד העזרה התחתונה.** עד גב מלבן הראשון: **שתים אמות.** ולא היה כן בבית עולמים ששם שנינו מביא מלבן של ל"ב על ל"ב וגובהו אמה וכאן גובהו שתים: **ורחב אמה אחת.** כשהניח מלבן השני עליו היה מלבן השני שלשים על שלשים נמצא כניסה לו סביב סביב רחב אמה והוא היסוד הרי עלה שתים וכנס אמה והוא היסוד י"ת עזרה מסמתא לשון רצפה שהיה ממלא את המלבן חלוקי אבנים מזפת וסיד וקוניא וממחה ושופך ומחליקו למעלה והרי הוא כמין רצפה: **ומהעזרה הקטנה עד העזרה הגדולה ארבע אמות.** מגג מלבן התחתון עד גג מלבן שעליו ארבע אמות גובה: **ורחב האמה.** הוא כניסת הסובב עלה ארבעה וכנס אמה זהו סובב והתחתון קורא קטנה לפי שאין גובהו אלא שתי' והעליון גובהו ארבע:
@107 **וההראל.** הוא גובה גג המזבח מן הסובב ולמעלה ובבית עולמים לא היה אלא שלש וי"ת אף הוא ומדבח' ארבע אמין:
@108 **והאריאל שתים עשרה אורך.** מקום המערכה היה עשרים וארבע על עשרים וארבע וזהו י"ב בי"ב: **אל ארבעת רבעיו.** שמאמצעיתו הוא מודד י"ב לכל רוח הרי כ"ד על כ"ד כך מפורש בזבחים וכן שנינו במסכת מדות המזבח היה ל"ב על ל"ב עלה אמה וכנס אמה זה היסוד נמצא ל' על ל' עלה חמש וכנס אמה זה הסובב נמצא כ"ח על כ"ח מקום הקרנות אמה מזה ואמה מזה נמצא עשרים ושש על עשרים ושש מקום הלוך רגלי הכהנים אמה מזה ואמה מזה נמצא כ"ד על כ"ד מקום המערכה:
@109 **והעזרה ארבע עשרה אורך.** גג המזבח עם מקום הקרנות ועם מקום רגלי הכהנים כ"ח על כ"ח וי"ד האמורים כאן מאמצעיתו מודד כמו שמפורש על ארבעת רבעיה: **והגבול סביב אותה.** י"ת וגדנפא ורבותינו פרשוהו על הקרנות: **חצי האמה.** מאמצעיתו מודד נמצא אמה על אמה: **והחיק לה אמה.** זו כניסת היסוד: **ומעלתהו פנות קדים.** וכבש שעולים בו היה בדרום כדי שיהא העולה בו פונה למזרח שכל הפינות היו דרך ימין וכשאתה נותן הכבש בדרום העולה בו ופונה דרך ימין פונה למזרח:
@111 **הכהנים הלוים.** אשר משבט לוי: **מזרע צדוק.** לפי שהיה ע"ג ששימש ראשון במקדש בימי שלמה נקראו על שמו:
@112 **על ארבע קרנותיו.** של מזבח: **פנות העזרה.** גג המזבח: **וכפרתהו.** תקנח אותו מדרך חול שבו להכניסו בקדוש' להיותו ראוי לכפר עליו מזה ולהלן:
@113 **במפקד הבית.** ת"י באתר דחזי לביתא כלומ' במקום קדוש ולשון במפקד הבית מקום שהבית כלה כמו ( מדבר לה ) לא נפקד ממנו איש והוא פר המלואים כדרך שעשו במשכן ונשרף אותו פר ולא נאכל וכן דרשו רבותינו במנחו' מלואים הקריבו בימי עזרא כדרך שהקריבו בימי משה:
@114 **תקריב שעיר עזים.** זה לא היה במשכן ובמלואים של לעתיד לבא כך הם על פי הדבור:
@115 **מחטא.** מלטהר:
@117 **תמימים יעשו.** לעולה:
@119 **ורצאתי.** לשון רצון:

@1 **כתית.** הרצון בו לפי הוראת הגדר שיהיו כותשין הזתים ויתנום בסל והשמן יורד מאליו בלי טעינת כלל הוא כשר למאור והוא השמן היותר נבחר למאור וראוי שתדע כי למאור נדקדק בשמן זית שיהיה כתית אבל לא נדקדק בזה בזמן המנחות שנאמר כתית למאור ביאר בזה כי למאור לבדו הוא שנקפיד בזה. ומזה המקום יתבאר כי מה שאמרה תורה בשמן המנחות שיהיה כתית אינו לעכב אבל למצוה מן המובחר:
@1 **להעלות נר תמיד.** למדנו מזה שצריך שידליק הפתילה באופן שיכול לעלו' הנר תמיד שתהא השלהבת עולה מאליה ויחוייב מזה שצריך ג"כ שישימו בנרות המנורה מהשמן בדרך שיתכן שיעלה הנר מהדלקה להדלקה שהיא בערב ובבקר כמו שהתבאר בסוף הפרשה ומה שאמר בכאן יערוך אותו אהרן ובניו מערב עד בקר אין הרצון בו שלא ידליק המנורה אלא בערב ולא תעלה נר ביום אבל הרצון בו שישימו בנרות המנורה מהשמן בשעור שיספיק מערב עד בקר והנה אמרה התורה מערב עד בקר ולא אמרה מבקר עד ערב לפי שימינו הם מתחילי' מהערב כמו שזכרנו במה שקדם. ולזה אין מחנכין המנורה אלא בערב כי הלילה קודמת ליום בימים התוריים ועוד כי מה שהולך במדרגת החסרון במה שתעיר עליו המנורה קודם בזמן למה שהולך במדרגת השלמות מצד מה שתאיר לצד קדש הקדשי' וזה מבואר מדברינו בפרש' הקודמת ולזאת הסבה היתה נקראת ההדלק' אשר בבקר ההטבה כי היא כאלו היא מתדלקת הערב אלא שעניינה הולך במדרגו' השלמות ממנה והנה רצתה התורה שתהיה הדלקת היום האחד נעשית בשני פעמים כמו שהיו י"ב תחלות אשר על השלחן בשתי מערכו' כמו שביארנו הסבה בזה במה שקדם והנה המצוה הזאת היא להעלות הנר בין הערבים ולהטיב הנרות בבקר ולפי שהנר האמצעי הוא שרש לשאר הנרות כמו שביארנו במה שקדם הנה אם ככה הנר האמצעי לא נדליק אותו משאר הנרות ואולם אם כבה אחת משא הנרות מדליקי' אותו מחברו כשנמשוך הפתיל עד הנר שככה כי הם יקחו אורם קצתם מקצת כמו שביארנו במה שקדם:
@2 **מחוץ לפרוכת אשר על עדות.** ר"ל אשר אצל העדו' כי לא היתה הפרוכת על העדות:
@3 **לכהנו לי.** הוא"ו נוספת הרצון בו לכהן לי. וענין זאת הכהנה הוא שדות הש"י בזאת העבודה הנזכרת בתורה:
@4 **לכבוד ולתפארת.** למדנו מזה שהוא מחוייב שיהיו אלו הבגדים באופן שיהיו לכבוד ולתפארת ואם לא היו בזה האופן כמו שבלו או נקרעו וכיוצא בהם פסולים:
@5 **אשר מלאתיו רוח חכמה.** למדנו מזה שכל חכמה שתהיה לאדם היא שופעת מהשם יתעלה וזה הוא האמת כמו שהתבאר בטבעיות ובא' ובה' ממ"י:
@5 **ועשו את בגדי אהרן לקדשו לכהנו לי.** למדנו מזה שבגדי כהונה הם מקדשין הכהן לכהן לשם יתעלה אבל בזמן שאין בגדי כהונה עליו אינו מקודש והרי הוא כזר שעבד שחייב מיתה:
@6 **חשן ואפוד ומעיל.** הנה יבא ביאורם במה שאחר זה:
@6 **כתנת תשבץ.** היא עשויה משש כמו שיתבאר אחר זה וענין השבוץ היא העשותה בתים בתי' כמו בית הכוסות. והנה תשבץ הוא שם:
@6 **מצנפת.** היא עשויה משש כמו שיתבא' והיה צונף בה כהן גדול ראשו צניפה על גבי צניפה.
@6 **ואבנט.** הוא ג"כ משש והיה כדמות חגורה לחגור בו על הכתונת והיו חוגרים בו כנגד הלב לא במקום בית השחי שכן פירש יחזקאל ולא יחגרו ביזע. רוצה לומר במקום שמזיעין בו:
@6 **לאהרן אחיך ולבניו לכהנו לי.** למדנו מזה גם כן כי הכהנים ההדיוטים םוהם בני אהרן אינן מקודשים לכהן לשם יתע' אלא בזמן שבגדי כהונה עליהן. וראוי שתדע שראוי שלא יהיה דבר חוצץ בין בשרם לבגדי כהונה שנאמר בפרשת אחרי מות ומכנסי בד יהיו על בשרו ורחץ במים את בשרו ולבשם וכן תמצא בפרשת צו מה שיורה על זה שנ' ויקרב משה את אהרן ואת בניו וירחץ אותם במים ויתן עליו את הכתונת למדנו מזה שלא היה שם דבר בין בשרו ובין הכתנת לולי המכנסי' שהיו חוגרים תחלה ואולם השמיט זכרם שם לכבוד משה:
@7 **והם יקחו את הזהב וגו'.** רוצה לומר החכמים העושים את המלאכה וכבר למדנו מזה המקום שאין עושין שדרה בממון בפחות משנים. והיה זה כן לפי שהאדם לא יחשוב שיעש' עון גדול כשיקח לעצמו מהממון שהוא מושל בו:
@8 **ועשו את האפוד זהב תכלת וארגמן ותולעת שני ושש משזר.** והם כ"ד חוטין מלבד הזהב ולמדנו שהם כ"ד חוטין לפי שהפשתן היה חוטו כפול ששה וחוטי התכלת והארגמן ותולעת שני ראוי שיהיו מתיחסים לחוטי הפשתן וזה מבואר מאד והנה הזהב היה חוט אחד ממנו עם כל אחד מאלו המינים ויהי החוטין כ"כ שנאמר וירקעו את פחי הזהב וקצץ פתילים לעשות בתוך התכלת והארגמן ולמדנו מזה שחוט של זהב היה כפול בתוכם. והנה היתה מלאכתו מעשה חושב שהצורות נראות משני צדדים באופן אחד והם נעשות באריגה לא במעשה מחט:
@9 **שתי כתפות חוברות יהיה לו.** הנה היו עושין הכתפות נפרדות מהאפוד ואחר כך תופרין אותם בראש האפוד בדרך שיהיו על כתפיו של אהרן:
@10 **וחשב אפודתו.** הוא כדמיון אבנט שהיה יוצא משני צדי האפוד והיה חוגר אותו כנגד לבו והוא ממלאכת האפוד בעצמה מכ"ח חוטים וממנו היה יוצא לכאן ולכאן כמו שתי רצועות:
@12 **ששה משמותם על האבן האחת.** ידוע כי הימין הוא היותר נכבד מהשמאל ולזה היה ראוי שתהיה התחלת פתוח השבטים באבן אשר בכתף הימנית. והנה היו שם כתולדותם אחד בכתף הימנית והשני כנגד השטח ההיא בכתף השמאלית כאלו תאמר שראובן היה ראשון בכתף הימנית ושמעון הראשון בכתף השמאלית. וכן בזה הדרך לא שיהיו ששה על הסדר בכתף האחד וששה על סדר בכת השנית. וזה דבר התבאר ענינו מן החוש למי שיראה אלו הכלים מרז"ל. ולזה אמר ששה משמותם על האבן האחת שאם היה הרצון שיהיו ששה מהם על הסדר בכתף האחד לא היה צריך לומר משמותם והנה העירנו בזה שאין הששה מסודרים על הסדר בכתף האחד:
@13 **מעשה חרש אבן.** רוצה לומר מעשה אומן האנים היקרות לפתח בהם מה שירצה:
@13 **מוסבות משבצות זהב.** הנה היה מקיף להם בית של זהב ובתוכו היתה נכנסת האבן:
@14 **אבני זכרון לבני ישראל.** רוצה לומר שהאבנים ההם תהיינה סבה שיזכור אהרן תמיד במחשבו בני ישראל ותשוטט בהם מחשבתו והנה בזה תועלת להגעת הנבואה בעניניהם כשהיה ראוי להגעת הנבואה כמו שביארנו בשני מספר מלחמות השם. והנה צורת האפוד היתה לפי מה שהאומר הוא היה כלי תלוי מאחורי הכהן ורחבו היה כרוחב גבו של כהן מכתף לכתף כדי שתהיינה הכתפות מחוברות לו והוא היה תלוי למטה מהכתפים שהוא כנגד בית השחי והכתפות מחוברות לו ונקפלות לפני הכהן מעט וכנגד הלב היה יוצא מהאפוד כמו חגורה משני צדדיו והיה חוגר בה על מעיל האפוד כמו שיתבאר אחר זה:
@15 **ועשית משבצות זהב.** רוצה לומר שיעשה מחוטין של זהב באריגה שתי חתיכות קטנות עשויות בתים בתים והיה מחובר אחד מהם בכתף האחד מהאפוד והאחר בכתף השנית והנה תועלתם היה לחבר החשן באפוד באמצעות השרשרו' שהיו נכנסות בטבעות החשן וקצותיהם קשורים במשבצות או תפורים בהם:
@16 **מגבלות תעשה אותם.** ר"ל שיגבילו המרחק שיש בין המשבצות ובין טבעות האפוד ויהייו בזה השיעור מכווני' ר"ל שיהיה ארכם כמו זה המרחק וידמה שהיה חוטם כפול תוך הטבעות מצד הטבעת בדרך שהיו מדובקים בזה האופן בטבעת וקצותיהם האחרים שהיו החוטים בהם נפרדים היו דבוקים במשבצות והנה אלו השרשראות היו נעשים מעשה עבות. והנה זאת המלאכה מפורסמת:
@17 **חשן משפט.** נקרא כן כי בו ישפוט הכהן על העתידות שישאלוהו מהם כמו שיתבאר והנה מלאכתו היתה כמלאכת האפוד והנה היו עושין אותו בשעור זרתים באורך וזרת ברוחב ואחר כך כופלי' אותו בדרך שיהיה זרת ארכו וזרת רחבו והנה אחשוב שהצד אשר היה בו ההכפל היה למעלה אצל הראש והנה היו בו ארבעה טורים מזהב נעשה כתי' בתים לשים בו י"ב האבנים שזכר ואמרו על אבן אחלמה שהוא מעיר הכח הדמיוני באופן שיחלום האדם הרבה כאשר ישאה והאבנים היו על שמות בני ישראל והנה היה כתוב באודם ראובן ובפטרה שמעון ובברקת לוי וכן על זה האופן. וכבר קבלו רז"ל שכתוב היה מלמעלה שם האבות והם אברהם יצחק ויעקב ולמטה שבטי יה וכבר היו על החשן שרשרות מגבילות מרחק החשן מהאפוד באופן שזכרנו למעלה וזה שכבר היה על החשן שתי טבעות למעלה בצד הנראה מן החשן ובטבעו' ההם היו מחוברו' השרשרות שרשרת אחת בטבעת האחת ואחר כך היו מחברים קצת שתי השרשרות על שתי המשבצו' אשר בשני כתפו' האפוד ובשני קצות החשן השפלות לצד בלתי נראה היו שתי טבעות זהב וכנגדם היו בכתפות האפוד שתי טבעות זהב והיה פתיל תכלת נתון לה באלו הטבעו' ובו יקשרו החשן עם האפוד מלמט' באופן שיהי חשב האפוד חגור מלמטה מפתיל התכלת כאמרו להיות על חשב האפוד:
@30 **ולא יזח החשן מעל האפוד.** הנה זאת האזהרה היא מצות לא תעשה ויתבאר שזאת האזהרה היה שלא יתפרק זה החיבור דרך קלקול לא שיהיה עובד המפרק אותו לתקנו וזה יתבאר ממה שאמר במעיל האפוד לא יקרע והנה הקריעה היא כל מה שיעשה דרך קלקול והשחתה וכזה יהיה אמרו לא יזח החושן מעל האפוד שלא יעשה זה דרך קלקול והשחתה וגם כן הנה יתבאר מצד הוראת הגדר כי אמרו לא יזח ר"ל פירוק חבורו דרך קלקול והנה היו שמות בני ישראל בחשן המשפט על לבו כי החשן היה על הלב כדי שתשוטט מחשבת הכהן הגדול בבני ישראל כי זה יישירהו אל שתבואהו ההודעה במה שיתכן שיקרה להם כמו שזכרנו במה שקדם אצל אבני האפוד והנה היו שם שמות האבות ושבטי יה לפי שמחבת הכהן תשוטט בשבטי' בצד שיוכללו בו ויהיו כלם כאחד לא בצד שיתחלקו בו כאו תאמר שתשוטט מחשבתו בכל שבט ושבט ביחוד כי הוא בלתי אפשר שתשוטט מחשבתו יחד בענינים חלוקים אם לא מהצד שיתאחדו בו:
@32 **ונתת אל חשן המשפט את האורים ואת התמים.** הנה לא בארה התורה איך היתה נתינת האורים והתומים בחשן המשפט ומה היו האורים והתומים לא זכרה איך יעשו אותם ומזה המקום נפל ספק בענינם והנה אמרו רז"ל שהאבנים האלה שהיו כתובים בהם שמות בני ישראל היו נקראים אורים ותומים מפני שמאירי' את דבריהם ומתממין את מעשיהם ואם היה הענין כן מה היה עושה משה בזה הענין שיתכן שתאמר התורה ונתת אל חשן המשפט את האורים ואת התומים ואמר גם כן בפרשת צו וישם עליו את החשן ויתן אל החשן את האורים ואת התומים וזה ממה שיביאנו להאמין כי האורים והתומים היה דבר מה נתן אותו משה אל חשן המשפט באופן שנתן העדות אל הארון שנאמר ונתת אל הארון את העדות אשר אתן אלך וידמה שהאורים והתומים היה דבר שלא היה בעשיו אומנות יצטרך שיעשה אותו איש אחר זולת משה וידמה שהיה ענינם ידוע מצד הוראת הגדר ולזה אמרו קצת הקודמי' שהיו שם כתבי שם המפורש וזאת הכתיבה עשה אותה משה וזה דבר נאות מאד לפי מה שאחשוב רוצה לומר שיהיו האורים והתומים דבר נכתב נתן בתוך החשן ולזה היה החשן כול והנה האורים והתומים היו מעירים הנבואה כשהיה הכהן ראוי לה כשהוא מסתכל בהם ולזה אמ' עליו ונשא אהרן משפט בני ישראל על לבו וה כי השמות הכתובים בחשן היו סבה אל שתשוטט מחשבת הכהן בישראל והאורים והתומים היו סבה להגיע הנבואה לו מצד התבוננותו בעצם הסבה הראשונה ויתבודד מפני זה שכלו מבין שאר כחות הנפש אשר הוא סבה להגעת הנבואה במה ששוטטה המחשבה בו ולזה ישא אהרן באמצעות הורים והתומים משפט בני ישראל על לבו כמו שזכרה התורה ולפי שהאורים והתומים היו העקר אשר אליו היתה הכונה היו נקראים אלו הבגדים אורים ותומים שנ' תומיך ואוריך. ושאל לו במשפט האורים. עד עמוד כהן לאורים ותומים. ולפי שזה כלו היה להעיד הנבואה לא היו נשאלים באורים ותומים אלא לכהן שרוח הקדש שורה עליו ולפי שמחשבתו לא שוטטה אלא בבני ישראל בכללם ולא היו נשאלים באחד אחד מהם אלא בדברים הכוללים והנה אחשוב בזה אחד משני ענינים אם שיהיו האורים ההתחלת ההיולאניות שהם סבות ההפסד כמו החומר הראשון והיסודות וקראם אורי' כי כמו שהאש הוא מפסיד כן הם מפסידים ולזה היה האש על המזבחות המורים על ההפסד והתומים הם ההתחלות הצוריות שהולכיות מהדברים ממדרגת התמימות והשלמות והנה מי שהתבונן באלו ההתחלות יתבאר לו שיש שם צורה ראשונה פועלת כל הנמצאות כמו שהתבאר בטבעיות ובמה שאחר הטבע תעתק מפני זה זאת ההשגה בשם יתע' ובשכלי' הנפרדים ותגיע לו הנבואה מפני זה הדבקות אשר לו בשם יתע'. ואפשר שיהיו האורים מיני החום הטבעי אשר לנמצא שהוא כלי לצורה להגיע פעולותיה לנמצא ההוא ולזה קראם אורים כי החום הטבעי הוא בנמצאות מפני מה שיש בו ביסוד האש שהתמזג בשאר היסודות ההתמזגות אשר ישלם בו החום הטבעי לנמצא ההוא והנה יהיה אלו החמימיות מתחלף מצד התחלף ההתמזגות כמו שהתבאר במקומותיו עד שהחום הטבעי אשר לאדם הוא זולת החום הטבעי אשר לסוס והחום הטבעי אשר לאבר אחד הוא זולת החום הטבעי אשר לאבר אחר מהאיברים והמשל שחום הכבד הוא זולת חום המוח ובזה האופן הנפלא ישלים השם יתעלה אלו הנמצאות וכבר התבאר במקומותיו שאין בידודו' די בהגעת כמו זה החום המשוער הטבעי ולה יחוייב שיהיה שפע זה החום מנמצא יותר נכבד מהיסודות והם הגרמים השמימיי' לפי מה שנתן להם הש"י מהכח ביום הבראם כמו שהתבאר במקומותיו. והתומים הם הצורות הנמצאות לאלו הדברים שלא יתכן המצאם מזולת צורה פועלת כמו שלא תבא צורת הכס' המוחשת אם לא מהצורה המושכלת אשר לה בנפש האומן. והנה יעתיקהו זה העיון אל העיון במה שישפע מהשם יתע' באמצעו' הגרמים השמימיים ובאמצעות הצורות אשר ישפיע באמצעותם נימוסי כל אלו הדברים אשר בכאן ובזה האופ' יגיעו לו העתידו' בנבואה. ואפשר שהיו האורים הכוכבים המאירים ולזה קראם אורים והנה היה הרצון בזה כי השם יתע' שם בהם כחות חלוקים עם היותם כלים מגשם לא קל ולא כבד עד שישלמו באמצעותם כל אלו הדברים אשר בכאן בניצוצים המגיעים לנו מהם כמו שביארנו בחמישי מספר מלחמות יי' והתומים הם הצורות אשר לגרמים השמימיים שהולכים במדרגת התמימות מהם ויכלה העיון בזה אל הסבה הראשונה כי נימוס אלו הדברים הוא מושפע מהם כמו ביארנו בחמשי מספר מלחמות יי' ומזה ההתבוננות שיהיה לכהן הראוי לנבואה באלו הענינים יהיה מוכן אל שתגיע לו הנבואה בענינים ששוטטה מחשבתו בהם והנה איך שיפורש מאלו הפירושים ענין האורים והתומים הכל הולך אל מקום אחת כי הכונה היתה להישיר הכהן אל שתגיע לו הנואה במה שישאלוהו ישראל מעניניהם הכוללים כמו שזכרנו במה שקדם וזה הביאור השלישי הוא היותר נראה לנו וידמה שזאת השאלה והמענה אשר בה לא היה כי אם בענינים הנופלים תכף כמו שנתפרסם ממה שזכר בשאלות ששאלו באורים ותומים ולזה היתה ההודעה בה יותר שלמה כי המקבל לא יתכן שישתנה בזה הזמן המועט בדרך שישתנה מה שיתכן מה שיקרה לו ולזה אמרו ז"ל כי אף על פי שיעוד הנביא חוזר היעוד המגיע באמצעות האורים והתומים אינו חוזר. והנה זה מבואר שמשפט האורים הוא מה שיודע לקוסם ומשפט האורים והתומים הוא מה שיודע לנביא כמו שביארנו בשני ובחמשי ממלחמות יי'. והנה ביארנו שם כי גם הקוסם או החולם יתכן שיצדק בענינים הנופלים תכף ואולי לזה אמר על אלעזר הכהן ושאל לו במשפט האורים כי אולי לא הגיעה מדרגתו אל שידע משפט התומים ועם כל זה כבר היה מספיק מפני שאת השאלה לא היתה כי אם בענינים הנופלים תכף:
@33 **ועשית את מעיל האפוד כליל תכלת.** כבר היה מבואר ממה שיורה עליו שם המעיל כי מלאכתו היתה עבה ושחוטו היה כפול שנים עשר. והנה היה כלו תכלת והנה היה כי ראשו כפול בתוכו בדרך שיהיה שפה לפיו סביב מבפנים כפי תחרא באופן שיראה חלק מבחוץ כמשפט כי בה יהיה יותר יפה והוא היה עושה מעשה אורג והזהיר שלא יקרע והנה הקורע אותו דרך השחתה לוקה כי הוא מחלל כבוד השם יתעלה והוא הדין לשאר בגדי כהנה לזאת הסבה בעינה. ואולם הודיעה זה התורה במעיל לפי שלא היה מכוון לעצמו אבל היה ממשמשי האפוד והחשן ולזה היה נקרא מעיל האפוד וכל שכן בשאר הבגדים המכוונים לעצמן. והנה צורת המעיל היא ידועה שאין לו בית יד כלל אבל יש לו מקום יכנס בו הראש ומקצתו תלוי לאחוריו ומקצתו לפניו ועליו היו מניחים האפוד ולזה נקרא מעיל האפוד והנה היה נראה בין כתיפות האפוד ולמעלה מן החשן ולמטה מעיל האפוד שהיה עינו כעין הרקיע שהוא כעין תכלת. ולזה לא היה בו כי אם תכלת ומזה המקום יראה שענין האוים ותומים היה לפי הביאור השלישי שבארנו והנה היו על שולי המעיל סביב רמוני תכלת וארגמן ותולעת שני וחוט כל אחד מהם היה כפול שמנה שכבר נאמר בפרשת ואלה פקודי רמוני תכלת וארגמן ותולעת שני משזר והנה משזר הוא מורה על החוט הנכפל שמנ' לפי הוראת השם והוא נגזר משזרה שהיא שדרה שיש בה צלעו' רבות והנה הרמונים היו בצורת הרמונים שלא פתחו פיהם והם כמו כדורים וכמותם היה ידוע מצד מספר החוטים שהיו בהם ולפי שרחב המעיל היה ידוע שהם כרחב גבו של אדם ועוד מעט הנה היה ידוע מספר הרמונים שהיו במעיל כי הפעמון היה שיעורו כשיעור הרמון זוג של זהב ועינבל בתוכו להכות בו כדי שישמע קולו. והנה היה המעיל סביב מוקף מפעמוני זהב ורמוני תכלת וארגמן ותולעת שני משזר וזה היה סבה שישמע קול אהרן בבאו אל הקדש ויעירהו להתבונן במה שהיה בקדש ובמה שהיה עליו מהבגדים לאיזה תכלית היה כי בזה תשלם הכונה האלהית הרצויה באלו הדברים ובזאת הסבה בעינה לא היה אפשר שיכנס שם הכהן אם היה שתוי יין כמו שיתבאר במה שיבא כי היין ימנעהו מהתבונן באלו הדברים כראוי. והנה מספר הרמונים היו שלשים וששה בצד שלפנים ושלשים וששה בצד שלאחור וכן מספר הפעמונים. בדרך שלא היה שם מקום פנוי שלא יהיה בו פעמון ורמון:
@38 **ועשית ציץ זהב טהור.** והנה הציץ היה מגיע מאוזן אל אוזן ולא היה מקיף הראש בשלמות אבל היה קושרו בפתיל תכלת שהיה נכנס בנקבים שהם בקרנות הציץ אצל האוזן והנה היה כתוב בו קדש ליי' ואם היה בשני שטין היה קדש מלמטה וליי' מלמעלה לחלוק כבוד לשם יתע' ולהורות שהוא עליון על כל הנמצאים ואם היה בשטה אחת היו כותבין בה קדש ליי' והנה האותיות היו בולטות בו שנאמר ופתחת עליו שיהיה הפתוח עליו ואולם באבני השוהם ואף על פי שנאמר בהם ופתחת עליהם כבר באר אחר זה שהאותיות היו שוקעות שנאמר תפתח את שני האבנים ועוד שכבר נאמר בציץ הפרשת ואלה פקודי מכתב פתוחי חותם וענין הכתיבה לפי הנהוג הוא שתהיה הכתיבה בולטת וגם כן הנה מפני שהכתיבה היא בולטת לפי הנהוג במקומות שאפשר זה הנה היתה הכתיבה בציץ בולטת כי זה היה קל להעשות בו. ואולם באבנים היתה הכתיבה הנהוגה שתהיינה האותיות חקוקות וכן היו כתובות שם לפי מה שאחשוב והנה קשה פתיל התכלת היה באחורי העורף על המצנפת שהיה צונף בה כהן גדול ראשו באופן שהיה חופהו כלו לבד מקום הנחת התפלין שהיה מגולח והוא היה בין המצנפת והציץ במקום שמוחו של תינוק רופס על מול פני המצנפת היה הציץ על מצח אהרן לא מאחורי העורף:
@40 **והיה על מצח אהרן ונשא אהרן את עון הקדשין.** למדנו מזה כי בזמן שהציץ הוא על מצח אהרן אז הוא נושא את עון הקדשים לא בזמן שאינו על מצח אהרן ואולם איזה עון הוא נושא לא נתבאר בכאן ואולם נלמד אותו ממה שאומר והוא שאי אפשר שישא עון הקדשים. אם היו פגול וישיב אותם להיות לרצון שכבר נאמר בפגול לא ירצה וכן לא ישא עונם אם היו בעלי מומין שהרי נאמר בהם לא ירצה המקריבין טמאין אף על פי שהם שוגגים ולא אם היו הקרבין טמאים אם היתה טומאתם ידועה כבר נתבאר זה כלו בתורה ונאמר כי מפני שמצאנו שעון הקדשים והמקדש שהיה הכהן מכפר עליו הוא הטומאה כמו שנתבאר בפרשת אחרי מות הנה זה העון הוא בהכרח עון טומאה ולפי שאי אפשר שיהיה בטומא הידועה מהטעם שזכרנו הנה יהיה העון שהוא נושא עון הטומאה בלתי ידועה כגון שנטמא המקריב בטומאת התחום שהוא בלתי ידועה לו ולא לזולתו כי זה הענין הוא למטה משגגת טומאה וכן אם נטמא הקרב ולא נודע עד שהקריב אמוריו הנה הציץ מרצה על כמו אלו הטמאות שנאמר את עון הקדשים רוצה לומר שגגת הקדשים הוא נושא אבל אינו נושא שגגת המקריבים והנה ישא מה שהוא למטה משגגה והוא אם נטמאו בטמאת התהום וזה דבר יתבאר מהשרשים הכוללים:
@40 **והיה על מצחו תמיד לרצון להם לפני יי'.** הנה מפני שהציץ בא לרצות עון הקדשים היה ראוי שיהיה על מצח אהרן בכל יום ויום כי הקרבנות היו קרבים בכל יום ויום. והנה היה זה אפשר כי כהן גדול היה מקריב ומשמש בכל יום אם ירצה. ולזה יתכן לו ללבוש בגדי כהונה בכל יום. והנה מזה המקום נלמד זה וזה כי בגדי כהונה לא יותרו ללבשם אלא מפני צרך העבודה ולפי שרצתה התורה שיהיה הציץ תמיד על מצח אהרן למדנו שהוא היה עובד בכל יום אם ירצה ולא יעכבוהו מזה אנשי המשמר ההוא:
@41 **ושבצת הכתנת שש.** היא עשויה מפשתן שחוטו כפול ששה והיא משובצת רוצה לומר שהוא עשויה בתים בתים והיו לה בתי ידים בדרך הלבוש השלם. ועשית מצנפת שש. המצנפת לא היתה משובצת והיתה עשויה מפשתן שחוטו כפול ששה. והנה היתה המצנפת ארוכה והוא צונף בה כהן גדול ראשו צנפה על גבי צנפה:
@41 **ואבנט תעשה מעשה רוקם.** היא האבנט היא חגורה שחוגר בה הכתונת. תחת אצילי ידיו כרך על גבי כרך וארוך היה מאד והוא היה נעשה משש ותכלת וארגמן ותולעת שני מעשה רוקם כמו שנתבאר בפרשת ואלה פקודי והאבנט היה כלאים כמו שאתה רואה. ולזה לא יותר הכהן ההדיוט לחגור בו אלא בשעת עבודה ואולם הכהן גדול יותר בכל הבגדים אפי' שלא בשעת עבודה מן הטעם שזכרנו:
@42 **ולבני אהרן תעשה כתנות.** הנה מלאכתם היתה כמלאכת כתונת כ"ג המו שנתבאר בפרשת ואלה פקודי. ואולם מלאכת האבנטים אינה כמלאכת האבנט של כהן גדול וזה דבר נתבאר בחוש דרז"ל ויש לו סמך עוד ממה שנאמר בזה בפרשת ואלה פקודי כמו שיתבאר שם. והנה אחשב שמלאכת אבנט של כהן גדול היתה יותר יפה במלאכתם ואולם באבנט של כהן הדיוט לא היה כי אם מין אחד של צמר:
@42 **ומגבעות.** הם תמורת המצנפת של כהן גדול אלא שכ"ג צונף בה והם מניחים אותה על ראשיהם כמין כובע:
@42 **לכבוד ולתפארת.** למדנו שאם אינם באופן שיהיו לכבוד ולתפארת הם פסולות כמו הענין בבגדי כהן גדול:
@43 **והלבשת אותם את אהרן אחיך ואת בניו אתו.** הראוי לאהרן לאהרן והראוי לבניו לבניו והם שמנה בגדים לכהן גדול וארבעה לכהן הדיוט:
@43 **ומשחת אותם.** בשמן המשחה:
@43 **ומלאת את ידם.** רוצה לומר שיקריב קרבנם אשר בו יכנסו לקדושת הכהונה כמו שיתבאר אחר זה:
@44 **ועשה להם מכנסי בד לכסות בשר ערוה ממתנים עד ירכים יהיו.** למדנו מזה שאין ראוי שיהיה במכנסים נקב תוכל להראות בו הערוה כי המכנסים ראוי שיהיו באופן שיכסו בשר הערוה ממתנים ועד ירכים היו. אין ראוי שיובן מסוף המתנים עד ראש הירכים כי אין ביניהם אמצעי ולא מסוף המתנים עד סוף הירכים כי לא יתכסה בהם הערוה כראוי. וכל שכן אם היו מראש המתנים עד ראש הירכים ולזה יהיה הרצון בזה מראש המתני' עד סוף הירכי' והיו על אהרן ועל בניו בבאם אל אהל מועד לכבוד השם יתע' בואם אל אהל מועד או בגשתם אל המזבח לעבוד עבודה שאם עבדו בזולת זה האופן חייבים מיתה בידי שמים.
@46 **פר.** הוא בן שתי שנים:
@46 **ואיל.** הוא משנכנס בשנה השנית אחד ושלשים יום וזה כלו לפי הוראת אלו השמו':
@47 **לחם מצו'.** ענינם ידוע ולא יה בהם שמן כלל והיו באים סולת חטי':
@47 **וחלו' מצות בלולות שמן.** הנה היה כולל הסולת בשמן ואח"כ לש אותם במים:
@47 **ורקיקי מצות משוחים בשמן.** היה עושה מצות רקיקות ולש אותם במים ואחר העשותן מושחן בשמן. והנה יתבאר שמספר כל מין ומין מאלו היה עשרה לפי שכבר ירים חלה אחת מכל מין כמו שיתבאר אחר זה והתרומה היותר גדולה שמצאנו בתורה היה אחד מעשרה והנה הביא יחד הפר והאילים והחלות ואע"פ שהם קרבנות חלוקות כמו שהתבאר מפני שבקבוצם תשלם הקדושה לאהרן ולבניו. וראוי שיהיה הכל מוכן בהתחלה כדי שימצא בזה הפועל השלמות בכל אופניו:
@49 **אל פתח אהל מועד.** ר"ל מבוא אהל מועד והיא העזרה כלה ר"ל חצר אהל מועד. וכן פתח דבריך יאיר ר"ל מבא דבריך והתחלתם:
@50 **והלבשת אהרן את הכתנת.** אין ספק שכבר לבשו תחלה המכנסי' אמנם לא זכרה התר' זה להתרחק מהזכיר דבר ערוה ואחר לבישתם הכתנה יחגרו אבנט אהרן ובניו כמו שאמ' אחר זה וחגרת אותם אבנט אהרן ובניו ואהרן ילבש אחר זה מעיל האפוד ואחר כן חוגר בחשב האפוד עליו וזהו שאמר ואפדת לו בחשב האפוד ועליו ישים החשן ובו יתן האורים והתומים כמו שנזכר בסוף סדר צו אמר שם ויתן אל החשן את האורים ואת התומים ואח"כ ישים המצנפת על ראשו ואח"כ יתן נזר הקדש על המצנפת והוא ציץ הזהב והציץ היה מול פניו כמו שאמר בפרשת צו וישם אל המצנפת אל מול פניו את ציץ הזהב נזר הקדש ויצקת על ראשו הנה היה יוצק משמן המשחה על ראשו מעט ומחת אותו כבר יתבאר ששמן המשחה לא נעשה ממנו שיעור רב והוא היה לדורות לא נעשו זולתן ולא יעשה ולזה הוא מבואר שזאת המשיחה לא היתה אלא בחלק מעט על הראש והיתה המשיחה שם כצורת כף יונית כמו שהיו מקובלים רז"ל מהנביאים שראו זאת המשיחה בעיניהם:
@53 **ואת בניו תקריב.** ר"ל שיביאם בחצר אהל מועד וזה אמנם היה בשנה השנית לצאתם מארץ מצרים כי אז הוקם המשכן והיתה להם כהנה לחקת עולם ר"ל שאחר זה לא יצטרכו לכמו זה הפועל לחדש להם כהנה אבל יהיו בניהם אחריה' לדורותם כלם כהנים ואולם לכהונה גדולה תצטרך משיחה וזה תמיד כי לא יתכן שיהיה בני הכהן הגדול כהנים גדולים כי לא יהיה שם כי אם כהן גדול אחד או ירצה בזה כי בזאת הלבישה תהיה להם כהונה תמיד לא כשלא יהיו לבושים אלה הבגדים כי אז הם במדרגת זרים לעבוד עבודתם:
@54 **ומלאת יד אהרן ויד בניו.** ר"ל שתשלים ידם ויכלתם לעבוד זאת העבודה אשר יעבדו בה באלו הקרבנות שתקריב עליהם כי אחר זה יהיה להן רשות ויכולת לעבוד לעבודתם והקרבת את הפר לפני אהל מועד הוא בחלק בחצר אהל מועד שהיה בו מזבח העולה כי אותו החלק ממנו היה לפני אהל מועד לא מה שהיה ממנו לצדדי אהל מועד ולאחוריו:
@55 **וסמך אהרן ובניו את ידיהם על ראש הפר.** הנה הסמיכה היתה בשתי ידי' וענינה היה להעיר על שהחטאי' נפרדו מהם וכאלו הושמו על זה הב "ח והוא מבואר שהנרצה בזה לא ישלם בסמיכה לבד אבל בתשובה ואמנם היה הסמיכה מעירה על התשובה והנה סמך תחלה אהרן ידיו ואחר כך כל אחד מבניו ומזה המקו' נלמד שהסמיכה יחוייב שתהיה בבעלי' לא בשלוחם ולה דקדקה התורה שיהיו כלם סומכים:
@56 **ושחטת את הפר לפני יי' פתח אהל מועד.** כבר יתב' במה שיבא ששחיטת החטאת היתה בחצר אהל מועד בחלק הצפוני במה שהיה ממנו לפני אהל מועד והנה לא היתה זאת השחיטה כשרה בזר כמו הענין בשחיטת שאר הקדשים לעוצם זה הענין וגדולתו וכן תמצא בעבודת יום הכפורים שלא היתה השחיטה כשרה כזר אבל היה השוחט כהן גדול ואמרו לפני יי' רצה בו שיהיו פני השוחט ליד קדש הקדשים:
@57 **ולקחת מדם הפר ונתת על קרנות המזבח באצבעך.** ר"ל אצל קרנות המזבח. והנה תמצא לשון התורה בחטאת על קרנות המזבח ובעולה על המזבח סביב וזה נמצא נכפל תמיד מתורה כזה האופן ולפי שמצאנו בעולת העוף וחטאת העוף על קיר המזבח ידענו שאין הזריקה על המזבח או על קרנותיו אבל היא על דפני המזבח. והננה דפני המזבח היו נחלקים לשני חלקים והחלק העליון הוא המתואר בשהוא אצל קרנות המזבח כי הם היו בעליונו והחלק התחתון הוא המתואר כשהוא אצל המזבח ולזאת הסבה ידמה שיהיה החלק במזבח כדי שיהיו קצת הדמים למעלה וקצתם למטה. והנה היה טובל אצבעו בדם ונותן על קרן אחת בחצי העליון מהמזבח כי הקרנות היו כלות שם אל ארבע קרנות נפרדות זו מזו. ואולם הקרנות אשר בחצי התחתון היו כלות אל היסוד שמחבר אותם כלם. והנה היו בחטאת ארבע מתנות מתנה אחת בכל קרן בחודה והיה על כל הזאת טבילה באצבעו להורות על הפרד אלו הקרנות. והנה היה זה הענין מיוחד בחטאת לפי שהוא בא לכפר על החטאי' הגדולי' וסבת החטאים החומר אשר יכלה ויפסד וישוב ליסודותיו שהם ד' כמו שהתבאר בטבעיות וכאלו יה זה הערה לעזוב אלו הדברים החומרי' אשר סופם אל ההפסד:
@57 **ואת כל הדם תשפוך אל יסוד המזבח.** הנה זאת השפיכה הית' אצל קרן מערבית דרומית כי הצד ההוא בחרתהו התורה בהגשת המנחה וחטאת העוף ועולת העוף כמו שהתבאר בספר ויקרא ושם התבאר הסבה בהיות זה הצד הנבחר ועוד כי מפני שאצל הקרן ההוא היתה ההזא' האחרונה ראוי שישפכו שירי הדם ביסוד אשר בצד ההוא כי הוא ראוי לזה כמו שאר חלקי היסוד ולזה אי' ראוי שיניחוהו לשפוך שירי הדם אל חלק אחר מהיסוד והנה בקרן ההוא לא היה שם יסוד אבל היו שם נקבים יכנס בהם הדם כי לא יאות שיהיה זה המקום הנכבד בטנוף זוהמת הדם והנה היתה הכונה בזה להרחיק ישר' מאכילת הדם ולזה היה דם כל הקרבנות נשפך במזבח ולא הותר להם לאכול בשר במדבר אם לא בשיעשו מהב"ח ההוא קרבן שלמים והיה המזבח אוכל החלב והדם בכללות עד שלא היה להם חלב ודם שיוכלו לאכלו כי לרוב הסתבכותם באכילת אלו המאכלים הנמאסים לבוחני האמת לא יוכלו להפרד מזאת התכונה והפחותה כי אם בזה האופן כמו שנבאר במה שיבא בג"ה והנה היה בזה תועלת שני והוא להעיר שישתמשו בדברים החמריי' לעבודת השם יתע' ולזה היתה שפיכת שאר הדם אצל החלק המערבי שהוא כנגד קדש הקדשים ולפאת דרום שהוא הימין כאלו יעיר בזה אל שנשים מנהגו בפעולות הגופיות אל הימין מהם שהוא המכוון והוא לעבודת השם יתע' והנה הקטיר מהפר המזבחה החלבים שזכר ויותרת הכבד כי מנהג כל חטאת ושאר הפר עם עורו ועם פרשו צוה לשרוף חוץ למחנה כמשפט חטאת הכהן שהיא נשרפת כמו שיתבאר הסבה במה שיבא:
@61 **וזרקת על המזבח סביב.** זאת הזריקה היתה למטה בחצי התחתון מהמזבח כמו שזכרנו במה שקדם והיה נותן שתי מתנות בשתי זויות האלכסון באופן שתהיה כל מתנה מהם מתפשטת בשני הרוחות ובזה האופן תהיה הזריקה סביב ואת האיל הנתח לנתחיו הם נתחי הבהמה הראשוני' אשר תחלק אליהם הבהמה לא הנתחים שיתחלקו עליהם נתחי הבהמה וכבר יתבארו אלו הנתחים איך הם במה שיבא עם זכירת הענין העולה בפרשת ויקרא בג"ה:
@65 **ונתת על תנוך אז אהרן וגו'.** הנה זה היה באופן כריתת הברית וזה שקצת הדם נתן על אהרן ועל בניו כאלו המקומות הנזכרים וקצתו על המזבח והנה היתה זאת הנתינה באלו המקומות הנזכרים כי האוזן הוא כלי השמיעה והידים והרגלים הם כלי העשיה כי ברגלים תהיה ההליכה ובידים תעשנה העבודות וכאלו העירם בזה שישתדלו לעשות אלו העבודות אשר יישירום אל זה ולזה היתה זאת ההזאה על האיברים האלו אשר לפאת ימין והנרצה בזה שתהיה שמיעתם ועשייתם ביותר נבחר שבדברים לעבוד השם יתע':
@66 **ולקחת מן הדם אשר על המזבח.** ר"ל הדם אצל המזבח שזרק קצתתו עליו ומהנשאר ממנו יקח משמן המשחה שיתבאר אחר זה אופן עשייתו והזה על אהרן ועל בגדיו ועל בניו ועל בגדי בניו ועל זה האופ' יקדשו הם ובגדיהם ולקחת מן האיל החלב והאליה וגו' הנה זה האיל השני היה במדרגת שלמים ולזה היה המזבח אוכל קצתו והבעלים קצתתו. והמקריב קצתו. וכבר יתבא' מהו האליה בענין הקרבנות ושוק הימין היה נאכל למזבח בזה הקרבן שהוא כמו שלמים ולא ימצא כן לזולתו והנה היתה הכונה בזה הענין בעצמו שכיון בנתינת הדם על תנוך אוזן הימנית ועל בהן היד הימנית ועל בהן רגל הימנית. ולזה נתן הסבה בזה ואמר כי איל מלואים הוא רוצה לומר שבו ימלא את ידם לכהן ולשרת לפני יי':
@69 **ושמת הכל על כפי אהרן וגומ'.** שהאימורים הנזכרי' והחלות הנזכרות ישים על כפי אהרן ועל כפי בניו. על כפי אהרן ראשונה ואח"כ על כפי כל אחד מבניו ומשה היה משים ידיו תחת כפיהם ומניף להעיר כי משה שהיה אמצעי בינם ובין השם יתע' יקרב אותם אל השם יתע' וכאלו יקח זאת המנחה מידם באמצעות משה. ועניין זאת התנופה יתבאר בשלמות בפרשת צו והחזה הרים משה לשם יתע' והיה למשה למנה שהיה כהן בזאת העבודה והוא אבי הכהונה והמוליד אותם כי ממנו נסתעפה לאהרן ולבניו כמו שנתבאר בזה המקום:
@72 **וקדשת את חזה התנופ' וגומר.** ידוע ממה שקדם כי שוק הימין מאיל המלואים הוקטר המזבחה והנה הרצון בזה שהחזה והשוק נתקדש מזה האיל שהוא שלמי' באופן שלא יאכלו אותם הבעלים והיה החזה והשוק משלמי ישראל לאהרן ולבניו לחק עולם כמו שנעשה בזה האיל שהיה שלמים והנה לא היה החזה והשוק מאיל המלואים למשה לפי שכבר הביא ההכרח שיהיה השוק קרוב בכמו שזכרנו ולפי שאמר לאהרן ולבניו למדנו שהכהן הגדול נוטל חלק בראש כי הוא קודם לבניו וכן למדנו בענין העבודה שהוא קודם לבניו ממה שאמר יערוך אותו ואהרון ובניו:
@74 **ובגדי הקדש אשר לאהרן יהיו לבניו אחריו.** הם בגדי כ"ג שנזכרו במה שקדם והרצון באמרו יהיו לבניו לאחד מבניו כי לא יהיה שם כי אם כ"ג אחד:
@74 **למשחה בהם** בשמן המשחה ובהם ימלאו ידם לשרת בקדש:
@75 **שבעת ימים ילבשם הכהן תחתיו מבניו.** למדנו מזה שהכהן הגדול כשהיו מקדשין אותו היה לובש בגדי כ"ג ופושטן ולובשן למחר עד שימלאו לו שבעה ימים ובכל יום ויום אלו השבעה ימים היה נמשח בשמן המשחה שנאמר ובגדי הקדש אשר לאהרן יהיו לבניו אחריו למשחה בהם ואח"כ ביאר ששבעת הימים ילבשם וזה לאות שכבר ימשח בהם באלו השבעה הימים ולפי שכבר אמ' למשח' בהם למלא בהם את ידם למדנו מזה שכיון שתלבש אותם פעם אחת ונמשח אם עבד עבודתו כשרה כי נמלאת ידו לשרת והנה בניו הם הכהנים ההדיוטים והנה יבחרו מהם היותר ראוי לכהונה גדולה. וראוי שתדע שאם היה בנו ראוי הנה הוא קודם לכל אדם כי המחזיק במעלה אין ראוי לעשקה ממנו מה שהתמיד להיות ראוי לה ממנו:
@76 **ובשלת את בשרו במקום קדוש.** הוא העזרה:
@77 **פתח אהל מועד.** הוא חצר אהל מועד והוא לפנים מן הקלעים כמו שנתבאר במה שקדם:
@78 **ואכלו אותם אשר כופר בהם.** בעבור שזכר אהרן ובניו יאכלו בשר האיל והלחם אשר בסל שהיה במדרגת שלמים באלו הקרבנות זכר עם זה שאותן הקדשים אשר כופר בהם והם החטאת והאשם כי הם הבאים לכפרה יאכלו גם כן אהרן ובניו הוא מצות עשה ולמדו רבותינו מזה המקום שבאכילת הכהנים יתכפר לבעלים. ובספרא למדו זה ממה שאמר ואותה נתן להם לשאת את עון העדה והנה התבאר הסבה בזה בג"ה בענין הקרבנות והנה אמרו למלא את ידם לקדש אותם שב אל מה שיהיה בו המאמר תחלה והוא אמרו ואכל אהרן ובניו את בשר האיל וגו' וזאת האכילה תהיה למלא את ידם בדרך שיהיה להם כח לשרת בקדש והנה הוכרחו רבותינו לבאר אמרו ואכלו אותם אשר כופר בהם בזה האופן לפי שאם היה שב אל בשר האיל והלחם היה בזה המאמר כפל ומותר או תהיה הכונה בזה באמרו למלא את ידם ולקדש אותם בעבור מלא ידם וקדושתם יאכלו אלו הקדשים ואמנם מי שאין ידו מלאה בזה האופן והם מי שאינם כהנים לא יוכלו לאכול מאלו הקדשים ויהיה שב אל מה שאמר ואכלו אותם אשר כופר בהם ותהיה הלמ"ד תמורת בעבור וכמוהו ימצאו רבים בלשוננו. והנה הרצון באמרו וזר לא יאכל כי קדש הם מי שאינו כהן שהוא זר אצל כהונה ופר חטאת תעשה ליום על הכפורים. ר"ל בכל יום משבעת ימי המלואים כי בכל יום יעשה כמו אלו הקרבנות שזכר בזאת הפרשה. והנה זכר החטאת לפי שכבר יחשב שלא יצטרכו לפר החטאת כי אם ביום הראשון ובו תשלם להם הכפורת ולזה זכר שבכל יום ויום יקריבו פר החטאת:
@81 **וחטאת על המזבח.** רוצה לומ' שיזה מדמו עליו:
@81 **ומשחת אותו לקדשו.** זאת המשיחה היא משמן המשחה והוא כמו כי יוני:
@82 **כל הנוגע במזבח יקדש.** רוצה לומר ממה שיהיה נוגע במזבח יקדש. רוצה לומר מה שדרכו שיהיה נוגע במזבח והא הדברים הראוים לו כי הם המתוארים בזה התואר ובא להרבות מה שהיה מהם נפסל משבא לעזרה כמו טמא ויוצא ולן וכיוצא בהם ואין ראוי שיובן שיהיה הרצון שיקדש הנוגע במזבח ממה שלא היה ראוי לו כלל כגון בהמה טמאה או בעל מום ומה שידמה להם כי אין זה ממה שדרכו שיתואר שיהיה נוגע במזבח כי הוא אינו ראוי לו כלל וראוי שלא יעלם ממנו הסבה בסדור אשר באלו הקרבנות וזה כי החטאת היה קרב ראשונה לכפרה וחלב מועט ממנו היה קרב לשם יתעלה כי הבעלים בלתי ראוים שיקח השם יתעהל מהם מנחה ודורון ואחר שנתכפר להם יקריבו עולה שהיא כלה לשם יתעלה להורות שהם מתקרבים לעבודת השם יתע' ואחד העולה יבא הקרבן שהוא במדרגת השלמים שקצו קרב לשם יתע' וקצו לכהנים וקצו לבעלים להורות שהם באהבה עם השם יתע' עד שיאכלו יחד על שלחן אחד:
@83 **וזה אשר תעשה על המזבח.** רוצה לומר ממה שיעשה בו תמיד ואולם הדברים אשר יעשו עליו לעתי' מה מהשנה יתבארו במה שיבא:
@84 **בין הערבים.** ר"ל בין שני הערבים והוא חצי היום והנה היתה עשייתו מחצי היום ואילך עד שיקעת השמש. ולפי שאמ' ואת הכבש השני תעשה בין הערבים למדנו שאין מחנכין את המזבח אלא בתמיד של שחר כדי שיהי תמיד של בין הערבים אף על פי שלא נעשה תמיד של שחר ביום ההוא שהרי הוא שני אצל המזבח:
@85 **בשמן כתית.** ר"ל שכותתין הזתים ונותנין אותו בסל והשמן היוצ' הוא שמן כתית. והנה זה התנאי אינו לעכב אלא למצוה וזה יתבאר ממה שאומר והוא שכבר נאמר בענין שמן המנורה כתית למאור למדנו מזה כי למאור לבד יצטרך כתית לא למנחות ועוד שבשאר המנחות לא זכרה התורה זה התנאי כמו המנחות הנזכרות בפרשת פנחס בענין המנחות הבאות עם המוספין וזה לאות כי לא תקפיד התורה בענין השמן הבא עם המנחות שיהיה כתית והנה הענין בעצמו יחייב זה כי למנורה ראוי שתקפיד התורה שיהיה שמן כתית כדי שיהיה נאות להעלות נר תמיד. ואולם השמן הבא עם המנחות לא היו משתמשין בו בדבר יצטרך להקפיד בו שיהיה כתית וזה מבואר מאד:
@85 **רובע ההין.** היא שלשה לוגין:
@86 **לריח ניחח אשה ליי'.** אחשוב שהרצון בזה הריח החזק לעורר המקריב הקרבן להתבונן בענין הקרבנות האלו למה היו כדי שיגיע בהם התועלת המכוון והיא הגעת הנבואה למי שהיה מהכהני' ראוי לה כמו שהיו הפעמונים במעיל האפוד לזאת הסבה כמו שזכרנו במה שקדם וכבר ביארנו איך יהיה מבוא בענין הקרבנות האלו להגעת הנבואה בפרשת נח:
@87 **פתח אהל מועד.** הוא העזרה כמו שקדם:
@87 **לפני יי' אשר אועד לכם שמה לדבר אליך שם.** הוא קדש הקדשים אשר היה מעיר אל ענין הגעת הנבואה כמו שקדם ומשם היא נראה רושם מוחש בהגיע הנבואה למשה כמו ענן ומה שידמה לו להורו' על הכונה במה שהיה שם שעם הוראתו על מציאות הצורות הנבדלות היה מורה על שפע האלהי אשר בו תהיה הנבואה והנה זכר זה בזה המקום להורות על שעקר הכונה בענין הקרבנות הוא להגיע הנבואה:
@88 **ונקדש בכבודי.** ר"ל ששם יראה כבודי:
@90 **ושכנתי בתוך בני ישראל.** רוצה לומ' שתדבק בהם השגחתי במה שיקנו מהשלמות בסבת המשכן והעבודה הנעשת בו ואהיה להם למנהיג להצילם מהרעות הנכונות לבא עליהם מצד מערכת הככבים באמצעות ההודעה אשר תבא להם בהם מצד הנבואה ואז יתבאר להם בראותם השגחתי הדבקה בהם כי אני יי' אלהים אשר הוצאתי אותם מארץ מצרים על צד ההשגחה הפרטית:
@92 **ועשית מזבח מקטר קטרת.** זה המזבח הוא מזבח פנימי ויקטירו בו קטרת הסמים בבקר ובין הערבים בעת הקרבת התמידין ואז ידליקו המנורה גם כן ומקומו היה בין השלחן הזהב והמנורה משוך בין שניהם לחוץ וכבר כרנו הסבה במה שקדם והנה יתבאר במה שיבא תואר קטרת הסמים אשר יקטירו בו:
@93 **ממנו קרנותיו.** בעבור שהמזבח מורה על ענין ההפסד כמו שקדם וההפסד יהיה מצד החומר אשר הוא חלק מורכב כשיפרדו יסודותיו וישובו לענינם הראשון דנה רצה שיהיו בו ד' קרנות כמספר היסודות שיהיו ממנו כי מהם נהיה המורכב והנה היה מכוון כנגד ארון העדות כי זה המזבח יורה על ההפסד האדם ושובו ליסודותיו ושוב נפשו אל האלהים אשר נתנה ולזה לא היה נעשה בו כי אם הקטרת קטרת הסמים ולזאת הסבה היו משימים בו מעלה עשן להעיר על עליית הנפש אל התחלתה בעת הפרדה מהחומר:
@98 **בהטיבו את הנרו'.** ר"ל בהדלקתו כהנרו' כי כבר ידליק אותם בבקר ובערב ולפי שסמך ענן הקטרת להדלקת הנרות למדנו שאין מחנכין מזבח הזהב אלא בקטרת של בין הערבים כמו שאין מחנכין את המנורה אלא בנרות של בין הערביים והענין הזה יתבאר במנורה ממה שאומר והוא שכבר אמר במנורה יערוך אותו אהרן ובניו מערב ועד בקר למדנו שהדלקת הערב הו' השרש וממנו תהיה ההתחלה ועוד שהכתוב קרא הדלקת הבקר הטבה והדלקת הערב העלה וההטבה לא תהיה כי אם בנרות שדלקו וזה מבואר בנפשו ולפי שבא זה בלשון הטבה לא היו מדליקין אותם יחד בבקר אבל היו מדליקין אותם יחד בערב אבל היו מדליקין קצתם פעם אחד וקצתם בפעם אחרת כמו שנזכר במסכת תמיד:
@100 **לא תעלו עליו קטורת זרה.** זולת הקטורת אשר יתבאר ענינה במה שיבא ולא עולה ומנחה ושאר הקרבנות כי זה המזבח לא ישמש זולתי להקטרת הקטורת והיא מצות לא תעשה:
@100 **ונסך לא תסכו עליו.** רוצה לומ' שלא ינסכו עליו יין או שמן כמו הענין במזבח החיצון והיא גם כן מצות לא תעשה לפי דעתי אך הרב המורה לא מנאה ודעתו רחבה מדעתנו:
@101 **וכפר אהרן על קרנותיו האחת בשנה.** רוצה לומר שיזה בהם ביום הכפורים כמו שיתבאר בפרשת אחרי מות והנה לא זכר עשיית מזבח הפנימי עם עשיית השלחן והמנורה אך המתין לזכור עשייתו עם זכירתו עשיית מזבח החיצון להורות שאלו שתי המזבחות יכוון בהם כוונה אחת בעינה כי שניהם מורים על ההפסדים אלא שמזבח הפנימי מורה על הפסד האדם אשר ישאר ממנו דבר בלתי נפסד והוא הנפש וזה היה מיוחד עניינו להקטרת הקטרת כמו שזכרנו והנה הסבה בזה זכרנוה עם זכירתנו ענין המנורה ושלחן הזהב ולפי שההויה יותר נכבדת מכל המורכבים זולתי האדם היה שלא יתחנך מזבח החצון כי אם בתמיד של שחר כי טבע היום הוא נאות להויה כמו שיתבאר למי שעיין בטבעיות. ולפי שההפסד באדם שהשלים נפשו יותר נכבד לו מההויה היה שלא יתחנך מזבח הזהב כי אם בקטרת שבין הערבים כי טבע הלילה הוא נאות להפסד ואמנם היה זה כן כי ההויה הוא באד' לזה התכלית בהפך הענין בשאר המורכבים וכן הענין בהדלקת המנורה כי היא תורה על ענין השגת שלמות האדם באמצעות כלי הנפש המרגשת עד שנרותיה יאירו מזה לצד הכרובים. וראוי שתדע כי ארון העדות היה לפאת מערב כדי להרחיק מנתינת האלהו' לשמש כמו שעשו הרבה מהתועי' הקודמים וזה כי בהשתחויתם אל היכל השם בבקר יהיו אחוריהם לשמש בעת שחיטתם תמיד של שחר ותמיד של בין הערבים וסמכו זה למה שאמר שנים ליום ר"ל לנגד היום אשר סבתו השמש ולזה היה נשחט תמיד של שחר בעזרה בקרן צפונית מערבית ותמיד של בין הערבים בקרן צפונית מזרחית ולזאת הסבה כונו גם כן שיהיה המדליק את המערכה בבקר באופן שיהיו אחוריו לצד מזרח כמו שנזכור בג"ה במה שיבא והנה התועלות המגיעות ממה שנכלל באלו הפרשיות התבארו מדברינו במה שקדם:

@1 **ואתה תצוה וגו' עד וזה הדבר אשר תעשה.**
@1 **ביאור דברי הפרשה:**
@1 **השרש** הראשון הוא שהשמן שהיו מדליקים בו את המנורה יחוייב שיהיה שמן זית זך כתית באופן שתעלה המנורה נר תמיד ולזה יחוייב שיהיה בה מהשמן בשיעור שיספיק להעלות נר מערב עד בקר כי בזולת זה לא ישלם שתעלה נר תמיד כי כבר יכבה בלילה ושערו חכמים שיהיה חצי לוג בכל נר כבר נתבאר זה השרש בראשון מיומא ובעשירי ממנחות ומזה המקום יתבאר שהוא מחוייב שתהיה הפתילה נכונה אל שתלקח בה השלהבת באופן שתהא השלהבת עולה מאליה כי בזולת זה לא ישלם לה שתעלה נר תמיד כבר נתבאר זה בשני משבת:
@1 **השרש** השני הוא שאין מחנכין המנורה אלא בהדלקת נרותיה בערב שנאמר מערב עד בקר למדנו מזה שהדלקת הערב היא הקודמת ולזה קרא בסוף הפרשה הזאת הדלקה אשר תהיה בבקר הטבה והנה הטבת ההדלקה היא הטבתה אחר ההדלקה בהכרח כבר נתב' זה השרש בד' ממנחות:
@1 **השרש** הג' הוא שהטבת הנרות הוא דישון הנר שכבה כשיסיר הפתילה וכל השמן שבו וישים בו פתילה חדשה ושמן והנה זה עם שהוא מבואר בעצמו למדנו אותו ג"כ מקל וחור מדשון מזבח החציון וזה שאם הקפידה התורה בה במזבח החציון כ"ש שתקפיד בזה במה שהוא בקדש כמו שמנורה ומזבח הזהב. והנה היה שם משים זה אל מקום הדשן הנזכר בפרשת ויקרא וזה מבואר מאד חיובו כבר נתבאר זה השרש בעשירי ממנחות:
@1 **השרש** הרביעי הוא שהדלקת המנורה יחוייב שיהיה מן האש אשר לפני יי' במזבח החיצון רוצה לומר מה שהיה ממנו כנגד קדש הקדשים כי ממנו יהיו לוקחין במזבח הקטרת כמו שיתבאר בפרשת אחרי מות ולה הוא מבואר כי בבקר אם כבה הנר האמצעי שהוא המערבי אין מדליקין אותו משאר הנרות כי הוא כמו שרש וראש להם כמו שהתבאר אך ידליקוהו ממזבח החציון ואמנם אם כבו שאר הנרות מדליק האחד חברו כבר התבאר זה השרש בשני משבת:
@1 **השרש** הה' הוא שהוא מואר מצד הוראת הגדר איכות עשיית אלו הבגדים והם בגדי כהן הדיוט היו מפשתן שחוטו כפול ששה זולת אבנט שהיה מצמר ופשתים והוא היה מכ"ד חוטין ששה של פשתן וי"ח משלשה מיני צמר שהם תכלת וארגמן ותולעת שני וכלם היו מעשה רוקם לא מעשה מחט אבל מעשה אורג וזה כלו שוה באלו הבגדים בבגדי כהן גדול ובבגדי כהן הדיוט כבר נתבאר זה בפרש' ואלה פקודי שנאמר ויעשו את הכתונת שש מעשה אורג לאהרן ולבש את המצנפת שש ואת פארי המגבעות שש ואת מכנסי הבד שש משזר ותכלת וארגמן וכבר נתבאר זה כלו בשביעי מיומא. והנה היו המכנסים מראש המתנים ועד סוף הירכים כדי שיכסו בשר הערוה שנאמר לכסות בשר ערוה נתבאר זה בשני מדנה. והציץ של כהן גדול לא היה אל מול פניו שנאמר והיה על מצחו תמיד והיה על המצנפת שנאמר אל מול פני המצנפת יהיה ולזה הוא מבואר שלא היה מקיף ראשו בכללות. אבל היה מגיע מאזן לאזן והיה נקשר בפתיל תכלת אחורי האזנים שנ' ושמת אותו על פתיל תכלת והנה היה שם רחב שתי אצבעות והיה כתוב בו בשני שטין קדש ליי' קדש ממטה ליי' מלמעלה להעיר על עליונות השם יתע' על כל הדברים כבר נתבאר זה בחוש לקצת רז"ל וכולם מלשון התודה יתבאר שאם כתב קדש ליי' בשטה אחת כשר כבר נתבאר זה בראשון בסוטה ובשני מגטין ואולם המעיל היה כלו מתכלת חוטו כפול י"ב וזה יתבאר מצד הוראת הגדר ונתבאר כמו כן מן החוש וחוטי שוליו כ"ד שמנה מכל מין שנאמר בהם משזר בפרשת ואלה פקודי ונאמר רמני תכלת וארגמן ותולעת שני משזר והנה היו הרמונים כצורת רמונים שלא נפתחו פיהם ותלו אותם במעיל ונתבאר מן החוש כי בכנף הרמונים היו. ומניח בכנף אצל כל רמון פעמון זהב כבר נתבאר זה בתשעה מזבחים. והנה האפוד היה מכ"ח חוטין ששה מכל מין ומין מארבעה המינין וחוט של זהב באמצע כמו שביארנו. והנה היה רחבו כרחב גב האדם והיה לאחוריו מתחת השחי עד הרגלים וכמו שתי ידות יוצאות ממנו שחובר אותו בהן כבר נתבאר זה בשביעי מיומא. והנה החשן היה מכ"ח חוטין כמו האפוד והיה ארכו ורחבו זרת וכופלו זרת ויהיה זרת ברובע וכן היו הארבעה טורים הנזכרים בתורה והיה כתוב בהם שמות השבטים כתולדות' וקודם להם היו כתובים בו שמות האבות והם אברהם יצחק ויעקב ואחריהם היה כתוב שבטי יה כמו שהתבאר זה מן החוש לקודמים מרז"ל וכבר התבארה הסבה בזה במה שקדם ובארבעה טבעות החשן היו טבעות בשתי מהם היה נתלה בשרשרות זהב ובשתי הטבעות התחתונים היה נקשר בפתיל תכלת בשתי טבעות שהיו כנגד טבעות המקום ההוא מאחוריו ותופר עליו תשתי כתפות יתחבר בהן החשן לאפוד ובכל אחד מהכתפות היה בה אבן היו בה ששה משמות בני ישראל בתולדותם כאלו תאמ' שבאבן הימנית תהיה כתו' ראובן בשטה אחת ואחר כך היה כתוב שמעון בשטה הראשונה מהאבן השמאלית וכן על הדרך הזה ולא היו כותבין ששה מהשמות בסדר באבן הימנית והששה הנותרים באבן השמאלית כי מפני שהיתה הכונה בזה שתתבודד מחשבת הכהן בענינים המשותפים לכל ישראל מצד מה שהם משותפי' להם היה שתהיה הכתיבה הזאת באופן שתחבר מה שבצד השמאל משמות השבטים למה שבצד הימין כי הכהן כשיתבונן באלו השמות בסדור לפי תולדות השבטים יחוייב לו שיביט בימין ובשמאל מצד מערב עם שכן היה סדור השבטי' בחשן ר"ל שהיו שמות השמאל נמשכים לשמות הימין בכל אחד מהשמות ולפי שדקדקה התור השיהיה מכפר השמו' שבצד השמאלי מן האפוד שוה למספר השמו' שבצד הימני היה נמשך מזה הדקדוק שהיה השווי נמצא בזה במספר האותיות אחר שכבר יה זה אפשר ולה היו כותבין יהוסיף עם אות הה"א. כבר נתבאר זה השרש בראשון מסוטה:
@1 **השרש** הו' הוא שהכהנים הם כזרים אצל העבודה בעת שאין בגדי הכהנה עליהם כמו שבארנו בביאורנו לזאת הפרשה והם ד' לכהן הדיוט וח' לכהן גדול ולזה אם היו בגדיהם יותר או פחות או שהיה שם דבר חוצץ בין בשרם ובגדיהם תהיה העבודה פסולה כבר נתבאר זה בשני ובשלישי ובתשיעי מזבחים ובז' מיומא:
@1 **השרש** הז' הוא שאלו הבגדים ראוי שיהיו לכבוד ולתפארת כמו שזכרה התורה ולזה הו' מבואר שאם בלו או נקראו באופן שלא יהיו לכבוד ולתפארת הם פסולין כבר נתבאר זה בשני מזבחים:
@1 **השרש** הח' שבגדי כהונה אינם באים אלא משל צבור כמו שיתבאר בפרשת כי תשא וכבר נתבאר זה בשלישי מיומא:
@1 **השרש** התשיעי הוא שבלבישתם הבגדים היו לובשים המכנסים תחלה והיו חוגרים למעלה מראשי מתניו ואחר זה לובשים הכתנת וחוגר באבנט כנגד אצילי ידיו אצל בית השחי שכבר פירש יחזקאל ולא יחגרו ביזע ואחר זה צונפים המצנפת כמו כובע וזה אמנם הוא כן בכהן הדיוט. ואולם כהן גדול אחר שחוגר באבנט לובש המעיל ועליו האפוד והחשן וחוגר בחשב האפוד על המעיל מתחת החשן ואחר צונף במצנפתו והיה קושר הציץ למעלה מן המצנפת והיה ריוח ביניהם להניח שם תפילין של ראש והיה זה כן כי מפני שהוא אפשר להניח מזולת שיהיה שם דבר חוצץ בין בגדי כהונה לבשר ההן ואולם בתפילין של יד אי אפשר זה ולא היו מניחי' תפלין של יד בשעת עבודה כבר נתבאר זה שהסדור היה בזה האופן מדברי התורה כבר תבאר זה בשני מזבחים:
@1 **השרש** העשירי הוא שאין נשאלים באורים ותומים אלא לכהן גדול שרוח הקדש שורה עליו כי הוא אשר אפשר שישא משפט בני ישראל על לבו מפני מה שהתבודדה מחשבו בענין השבטים ואין נשאלים בהם אלא לדברים כוללים לכל ישראל כי לזאת הסבה היו שמות השבטים כלם על לב הכהן ולזה אין נשאלין אלא למלך אל לב"ד או למי שצרך הצבור בו שנ' ולפני אלעזר הכהן וגו' הוא וכל בני ישראל וכל העדה והנה היה יהושע מלך כבר נתבאר זה השרש בז' מיומא:
@1 **השרש** הי"א הוא שהציץ מרצה עון הקדשים בזמן שהוא על מצחו וזה אמנם הוא כשנטמ' המקריב בטמאת התהום שלא היתה ידועה או שנטמאו הקדשים ולא נודע לכהן עד שהקריב אמוריו שנ' והיה על מצח אהרן כמו שבארנו ממה שקד לביאורנו זה הפסוק כבר נתב' זה השר' בששי מפסחים:
